do $training$
declare p jsonb := $payload${"revision":"ai-practice-training-2026-10-26-v3","checked_at":"2026-10-26","course":{"title":"ИИ с нуля: текст, медиа, автоматизация и вайбкодинг","subtitle":"5 модулей · 14 уроков · практика с бесплатными и платными сервисами","description":"Базовое обучение для новичка: пойми возможности ИИ, выбери инструмент и создай собственный результат.\n\n1. **Знакомство с ИИ** — модели, агенты, инструменты, плагины, коннекторы, Skills, MCP и OpenBot.\n2. **Работа с текстом** — исследования через Agent Reach, проверка фактов, запросы и редактирование.\n3. **Работа с медиа** — изображения, видео, голос и музыка: от идеи до монтажа.\n4. **Автоматизация** — сначала встроенные задачи ChatGPT, Claude и Gemini, затем n8n: данные между шагами, ошибки и повторы.\n5. **Вайбкодинг** — первая страница, отдельная практика в OpenCode и итоговый проект.\n\nВ каждом уроке: объяснение, разобранный пример, шаги, самостоятельная работа, проверка и ссылки. Есть схемы, управляемые учебные анимации и файлы для практики. Показаны бесплатный старт, ограничения и причины перехода на платный доступ; покупка подписок не является условием прохождения. Ориентир — около 9 часов с практикой. Возможности и условия сверены по официальным страницам на 26 октября 2026. Каталог обзоров инструментов находится в новостях."},"lessons":[{"key":"block-1","title":"1. Что умеет ИИ и как выбрать первый инструмент","subtitle":"Составишь бриф, по которому можно принять или отклонить результат ИИ.","body":"Модуль 1 · Знакомство с ИИ\n\nАктуальность: 26 октября 2026. Лимиты и доступность сверяй в своём аккаунте перед запуском.\n\n## Чему научишься\n\nСоставишь бриф, по которому можно принять или отклонить результат ИИ.\n\nОриентир: 25 минут вместе с практикой. Сохраняй файлы: они пригодятся в итоговом проекте.\n\n![Схема урока](https://elaz-ed.vercel.app/learning/ai-practice/lesson-1.png)\n\n## Как это работает\n\nМодель предсказывает подходящий ответ, а не знает твои скрытые ожидания. Поэтому «сделай хороший пост» оставляет ей слишком много решений: для кого писать, какой факт главный, можно ли придумать цифры. Хорошее задание задаёт входные данные, действие, ограничения и критерий результата.\n\nВ этом курсе мы готовим запуск вымышленного клуба «Фокус»: сначала исследование, затем текст, визуал, короткий ролик и повторяемый процесс. Можно заменить клуб своим проектом. Учебные данные: онлайн-встреча 7 ноября в 19:00 по Алматы, длительность 45 минут, 20 мест, участие бесплатно, тема — первая полезная автоматизация. Эти данные вымышлены и нужны только для упражнений.\n\nОтделяй цель от формата. Цель — человек понимает, подходит ли ему встреча. Формат — пост до 700 знаков. Ограничение — не обещать доход или результат, которого нет в брифе. Критерий — указаны время, тема, формат и следующий шаг.\n\n### Что обновилось к 26 октября 2026\n\nУ Claude актуальная линейка 5.5: Opus 5.5, Sonnet 5.5 и Haiku 5.5. Выбирай доступную модель по задаче и тарифу, а не по старому скриншоту. В новом приложении Claude чат и Cowork объединяются; обновление приходит аккаунтам постепенно. Claude Desktop, Claude Code и OpenCode — разные продукты, хотя в них могут использоваться модели одного провайдера. Для новичка основной путь — приложение.\n\nВ OpenCode используем актуальное руководство V2 и Desktop, в озвучке учитываем Eleven v4. Название сервиса и название выбранной модели записывай отдельно: “приложение обновлено” не означает, что в нём автоматически выбрана новая модель.\n\n## Какие инструменты выбрать\n\n| Что нужно сделать | Какой тип ИИ выбрать | Пример применения |\n|---|---|---|\n| Текст и идеи | Чат с языковой моделью | План, письмо, объяснение сложного текста |\n| Разобраться в материалах | Поиск + чтение источников | Сравнение решений с прямыми ссылками |\n| Картинка | Генератор изображений + редактор | Фон, иллюстрация, обложка с текстом отдельными слоями |\n| Видео | Генератор сцен + монтаж | Оживить картинку, собрать короткий ролик |\n| Голос | Распознавание или синтез речи | Субтитры из записи, озвучка из текста |\n| Музыка | Музыкальный генератор | Подложка без вокала, демо песни |\n| Сайт и скрипт | Помощник для кода | Локальная страница, калькулятор, проверка файла |\n| Повторяющийся процесс | Редактор автоматизаций | Получить данные → обработать → сохранить результат |\n\nМодель — движок, сервис — приложение вокруг него. Один сервис может давать несколько моделей и разные лимиты. Чат предлагает ответ; агент ещё и выполняет разрешённые действия инструментами. Автоматизация запускает заранее собранные шаги по событию. Не нужно начинать с команды агентов, если достаточно одного чата.\n\n## Бесплатно и платно\n\nДля текста и учебных экспериментов можно начать с Google AI Studio: на официальной странице есть бесплатный доступ с ограничениями к определённым моделям. Используй только вымышленные данные: для бесплатного уровня указаны отдельные условия обработки содержимого. Платный API нужен при подходящих объёмах и требованиях, но для первого брифа оплачивать его не требуется. Подписка на чат и счёт API — разные способы оплаты.\n\n## Первый запуск\n\n### Первый запрос в ChatGPT — веб-версия\n\nДля каждого шага смотри три вещи: что нажать, зачем и какой результат проверить. Английские названия оставлены рядом с русскими, чтобы их можно было найти в интерфейсе.\n\n#### Шаг 1\n\n**Куда нажать / что ввести:** Открой chatgpt.com и выбери New chat / «Новый чат».\n\n**Зачем:** Начать без старой переписки, которая может повлиять на ответ.\n\n**Что должно появиться:** Пустое поле сообщения. На телефоне список чатов может быть спрятан в боковом меню.\n\n#### Шаг 2\n\n**Куда нажать / что ввести:** Вставь в поле учебный бриф из ссылки внизу урока. Под ним напиши: «Составь анонс до 700 знаков, не добавляя факты».\n\n**Зачем:** Дать модели исходные данные и конкретный результат.\n\n**Что должно появиться:** В поле есть и факты, и задание — не только фраза «напиши пост».\n\n#### Шаг 3\n\n**Куда нажать / что ввести:** Нажми кнопку отправки рядом с полем сообщения.\n\n**Зачем:** Запустить ответ.\n\n**Что должно появиться:** Появился текст анонса. Его наличие ещё не означает, что факты правильные.\n\n#### Шаг 4\n\n**Куда нажать / что ввести:** Отправь уточнение: «Сверь дату и время с брифом. Перечисли добавленные тобой факты».\n\n**Зачем:** Научиться исправлять ответ отдельным действием.\n\n**Что должно появиться:** Ты видишь проверку; сам сравни её с брифом и сохрани выбранную версию.\n\n**Если экран отличается:** Если ChatGPT недоступен, выполни тот же запрос в доступном чате: новый диалог → поле сообщения → отправка → уточнение.\n\n## Разобранный пример\n\nПлохо: «Ты лучший маркетолог. Напиши продающий текст».\n\nЛучше: «По учебному брифу клуба Фокус напиши пост для новичка до 700 знаков. Укажи дату, время с часовым поясом, длительность и тему. Не добавляй гарантии и отзывы. Заверши фразой “Сохрани дату”; регистрационной ссылки пока нет. После текста перечисли данные, которых не хватает для публикации».\n\nЕсли модель добавила “только сегодня” или выдуманную ссылку, результат не проходит критерии, даже если выглядит убедительно.\n\n## Сделай по шагам\n\n1. Создай папку проекта и файл brief.md. Запиши аудиторию, одну цель, проверенные факты, формат и запреты.\n\n2. Добавь 4 критерия приёмки. Каждый должен давать ответ «да/нет»: например, время указано с часовым поясом.\n\n3. Дай запрос выбранной модели и сохрани первый ответ как draft-01.md.\n\n4. Проверь ответ по критериям. Правь один обнаруженный дефект за проход; сохрани вторую версию и список изменений.\n\n## Самостоятельная работа\n\nНапиши собственный бриф на 8–12 строк. Получи два варианта поста и выбери один по критериям, а не по ощущению. Сохрани brief.md, draft-01.md, draft-02.md и три причины выбора.\n\n## Критерии готовности\n\nВ тексте есть четыре обязательных факта; нет придуманных ссылок, отзывов и гарантий; длина соответствует брифу; неизвестное перечислено отдельно.\n\n## Проверь себя\n\nМодель добавила скидку, которой нет в брифе. Надо ли улучшить стиль или убрать утверждение?\n\nСначала ответь своими словами, затем сравни с разбором.\n\n## Разбор ответа\n\nСначала убрать неподтверждённое утверждение и усилить ограничение в брифе. Стиль не исправляет фактическую ошибку.\n\n## Ссылки для практики\n\n- [Скачать учебный бриф](https://elaz-ed.vercel.app/learning/ai-practice/brief.md)\n- [AI Studio: начать](https://aistudio.google.com/)\n- [Бесплатный и платный API: условия](https://ai.google.dev/gemini-api/docs/pricing)\n- [Claude: текущие модели](https://www.anthropic.com/system-cards)\n- [Claude: объединение чата и Cowork](https://support.claude.com/en/articles/16761823-claude-cowork-and-chat-are-one-claude)\n\nСледующий шаг: сохрани результат этого урока и переходи к следующему.","cover_url":"https://elaz-ed.vercel.app/learning/ai-practice/lesson-1.png","minutes":25,"position":1,"category":"Модуль 1 · Знакомство с ИИ"},{"key":"block-connections","title":"2. Плагины, коннекторы, Skills и MCP без путаницы","subtitle":"Разберёшься, чем отличаются способы расширения ИИ, и опишешь одно подключение с нужными правами.","body":"Модуль 1 · Знакомство с ИИ\n\nАктуальность: 26 октября 2026. Лимиты и доступность сверяй в своём аккаунте перед запуском.\n\n## Чему научишься\n\nРазберёшься, чем отличаются способы расширения ИИ, и опишешь одно подключение с нужными правами.\n\nОриентир: 30 минут вместе с практикой. Сохраняй файлы: они пригодятся в итоговом проекте.\n\n![Схема урока](https://elaz-ed.vercel.app/learning/ai-practice/lesson-2.png)\n\n## Как это работает\n\nПредставь помощника, которому нужно подготовить отчёт по документам. Сама модель рассуждает и пишет. Инструмент выполняет конкретное действие: ищет файл или читает таблицу. Коннектор связывает приложение с внешним сервисом и его учётной записью. Плагином часто называют пакет возможностей; точный состав зависит от приложения. Skill хранит повторяемые инструкции и вспомогательные материалы.\n\nMCP — протокол связи между ИИ-приложением и серверами, предоставляющими инструменты и контекст. Приложение выступает хостом, клиент поддерживает соединение, сервер объявляет возможности. MCP не является отдельной моделью и не делает недоступные данные автоматически доступными. Нужны поддержка со стороны приложения, подходящий сервер и разрешения.\n\nAPI — интерфейс отдельного сервиса; ключ API подтверждает доступ. OAuth позволяет разрешить доступ через вход в сервис. Это не взаимозаменяемые названия и не способ получить платный сервис бесплатно. При подключении важно понимать, какой аккаунт выбран и что именно разрешено: читать, менять или публиковать.\n\n## Какие инструменты выбрать\n\nВыбирай встроенный коннектор, если он уже решает задачу. MCP полезен, если приложение и сервер поддерживают нужный инструмент. Skill нужен для процедуры. Плагин может объединять несколько таких частей.\n\n## Бесплатно и платно\n\nСамо название MCP не означает платный или бесплатный доступ. Отдельно учитывай стоимость приложения, модели, сервиса и размещения сервера. Для учебной карты доступа ничего покупать не нужно.\n\n## Первый запуск\n\n### Где искать подключения — пример ChatGPT\n\nДля каждого шага смотри три вещи: что нажать, зачем и какой результат проверить. Английские названия оставлены рядом с русскими, чтобы их можно было найти в интерфейсе.\n\n#### Шаг 1\n\n**Куда нажать / что ввести:** Открой Settings / «Настройки» → Apps / «Приложения».\n\n**Зачем:** Посмотреть, какие сервисы действительно поддерживаются в аккаунте.\n\n**Что должно появиться:** Список приложений; каталог может зависеть от рабочего пространства.\n\n#### Шаг 2\n\n**Куда нажать / что ввести:** Открой карточку одного нужного приложения и прочитай список разрешений до подключения.\n\n**Зачем:** Сопоставить доступ с задачей. Для поиска по документам не нужна отправка сообщений.\n\n**Что должно появиться:** Понятно, какой сервис и какие данные запрашиваются.\n\n#### Шаг 3\n\n**Куда нажать / что ввести:** Если решишь подключить, выбери нужную учётную запись и проверь разрешения на экране авторизации.\n\n**Зачем:** Не выдать доступ случайному аккаунту.\n\n**Что должно появиться:** Подключение подтверждено интерфейсом, а не только ответом чата.\n\n#### Шаг 4\n\n**Куда нажать / что ввести:** Вернись в новый чат и попроси прочитать один учебный документ; проверь его название и содержание в ответе.\n\n**Зачем:** Убедиться, что интеграция действительно читает нужные данные.\n\n**Что должно появиться:** Ответ совпадает с документом. В настройках приложения найди способ отключения.\n\n**Если экран отличается:** Нет нужного приложения — вставь учебный текст вручную. MCP и коннекторы зависят от конкретного приложения; одно меню не является универсальным для всех сервисов.\n\n## Разобранный пример\n\nЗадача: найти в учебной папке время встречи и предложить текст анонса. Нужны поиск и чтение. Право удаления файлов и отправки постов для этого не требуется.\n\nВ таблице доступа запиши: сервис — файловая папка; данные — только brief.md; действия — чтение; выход — черновик; подтверждение — перед публикацией. Если готового коннектора нет, можно вручную передать учебный файл: цель упражнения — правильно определить границу доступа, а не подключить всё подряд.\n\n## Сделай по шагам\n\n1. Выбери одну задачу из своей работы и нарисуй цепочку: приложение ИИ → инструмент или коннектор → данные → результат.\n\n2. Подпиши, где находится модель, где данные и где проверяется доступ. Отдельно выпиши действие, которое меняет что-либо вне чата.\n\n3. В используемом приложении открой список подключений или инструментов. Выбери одну подходящую интеграцию, прочитай разрешения. Если она требует установки или оплаты, сначала выполни упражнение вручную с учебным файлом.\n\n4. Сделай запрос на чтение тестового материала. Убедись, что ответ основан на его содержимом. Затем запиши, где отключается доступ. Не вставляй ключи в публичный код или в общий учебный отчёт.\n\n## Самостоятельная работа\n\nПодготовь access-map.md: задача, приложение, инструмент, источник данных, права, подтверждаемые действия и способ отключения. Объясни своими словами разницу между MCP, коннектором и Skill.\n\n## Критерии готовности\n\nНазвания не смешаны; для чтения не запрошена публикация; понятно, какой аккаунт и файл используются; ключей нет в учебном отчёте; доступ можно отключить.\n\n## Проверь себя\n\nЕсли приложение поддерживает MCP, можно ли подключить любой сервис без его разрешения?\n\nСначала ответь своими словами, затем сравни с разбором.\n\n## Разбор ответа\n\nНет. Протокол задаёт способ общения, а не отменяет авторизацию, лимиты или условия сервиса. Нужны совместимый сервер и разрешённый доступ.\n\n## Ссылки для практики\n\n- [MCP: устройство протокола](https://modelcontextprotocol.io/docs/2026-07-28/learn/architecture)\n- [Skills: устройство навыка](https://agentskills.io/)\n- [MCP-подключения в OpenCode](https://opencode.ai/docs/mcp-servers/)\n\nСледующий шаг: сохрани результат этого урока и переходи к следующему.","cover_url":"https://elaz-ed.vercel.app/learning/ai-practice/lesson-2.png","minutes":30,"position":2,"category":"Модуль 1 · Знакомство с ИИ"},{"key":"block-openbot","title":"3. Собери команду в OpenBot и передавай результат","subtitle":"Настроишь две роли с явными входами, файлами результата и правилами передачи работы.","body":"Модуль 1 · Знакомство с ИИ\n\nАктуальность: 26 октября 2026. Лимиты и доступность сверяй в своём аккаунте перед запуском.\n\n## Чему научишься\n\nНастроишь две роли с явными входами, файлами результата и правилами передачи работы.\n\nОриентир: 40 минут вместе с практикой. Сохраняй файлы: они пригодятся в итоговом проекте.\n\n![Схема урока](https://elaz-ed.vercel.app/learning/ai-practice/lesson-3.png)\n\n## Как это работает\n\nНесколько агентов полезны, если между задачами есть понятная граница. Исследователь отвечает за таблицу свидетельств. Редактор — за текст по этой таблице. Проверяющий — за ошибки относительно критериев. Если все одновременно «делают всё», расходы растут, а ответственность теряется.\n\nВ OpenBot у агентов есть инструкции и рабочие пространства; они могут обмениваться сообщениями и файлами. Название продукта на официальном сайте — OpenBot. Это отдельный продукт, не OpenClaw. Подключи доступного провайдера по инструкции своей версии, затем начни с изолированной учебной папки.\n\nРабочие файлы хранятся на компьютере, где запущено приложение, но облачный провайдер получает отправленные ему запросы. Для совместной работы заранее проверь, какие пути действительно доступны каждой роли. Не считай, что файл из одной папки автоматически виден всем.\n\nЭто вводная проба: используй бриф и две учебные строки фактов. Полное исследование и сравнение источников пройдёшь в модуле «Работа с текстом». Вернуться к этой передаче можно после него.\n\n## Какие инструменты выбрать\n\nOpenBot объединяет агентов и рабочие пространства. Его стоит выбирать для последовательных или параллельных задач с файлами. Для одного простого вопроса хватит чата; Agent Reach дополняет чтение источников, но не заменяет рабочее пространство.\n\n## Бесплатно и платно\n\nНа официальном сайте OpenBot приложение заявлено бесплатным; используемый провайдер и его лимиты оплачиваются или предоставляются отдельно. Код имеет PolyForm Noncommercial, поэтому перед коммерческим применением проверь лицензию. Не путай бесплатную загрузку приложения с бесплатной работой любой подключённой модели.\n\n## Первый запуск\n\n### Первая проба в OpenBot\n\nДля каждого шага смотри три вещи: что нажать, зачем и какой результат проверить. Английские названия оставлены рядом с русскими, чтобы их можно было найти в интерфейсе.\n\n#### Шаг 1\n\n**Куда нажать / что ввести:** Открой openbot.run → Download и выбери свою операционную систему.\n\n**Зачем:** Установить именно OpenBot; это отдельный продукт.\n\n**Что должно появиться:** Установщик подходит твоей ОС. Следуй инструкции установки на сайте.\n\n#### Шаг 2\n\n**Куда нажать / что ввести:** После запуска подключи одного доступного провайдера по подсказкам приложения.\n\n**Зачем:** Выбрать модель, которая будет выполнять задачу.\n\n**Что должно появиться:** Есть подтверждение подключения. Условия провайдера проверь до включения оплаты.\n\n#### Шаг 3\n\n**Куда нажать / что ввести:** В создании агента опиши одну роль: «Редактор учебного анонса, читает brief.md, создаёт draft.md, не публикует».\n\n**Зачем:** Ограничить первое поручение понятным результатом.\n\n**Что должно появиться:** В инструкциях агента видны роль, разрешённая папка и результат.\n\n#### Шаг 4\n\n**Куда нажать / что ввести:** Открой разговор с агентом, дай учебный бриф и отправь поручение. Затем открой созданный draft.md.\n\n**Зачем:** Проверить реальный файл вместо обещания «готово».\n\n**Что должно появиться:** Файл существует, читается и совпадает с брифом. Только после этого добавляй вторую роль.\n\n**Если экран отличается:** Названия экранов OpenBot зависят от версии. Если нет установки или подходящего провайдера, отработай передачу в двух чатах по инструкции урока, не называя это запуском OpenBot.\n\n## Разобранный пример\n\nПередача: «Готов evidence.csv. Проверены 6 строк, две цены не подтверждены. Редактор: используй только строки со статусом checked; неизвестное не добавляй. Сохрани draft.md, затем верни путь и список использованных строк».\n\nТакое сообщение полезнее «я закончил, продолжай»: оно содержит артефакт, ограничения и ожидаемый выход.\n\n## Сделай по шагам\n\n1. Установи OpenBot с официального сайта, если он подходит твоей системе. Подключи провайдера и проверь условия доступа и лицензии для своего сценария.\n\n2. Создай исследователя: только чтение учебного брифа и запись двух проверенных фактов в evidence.csv. Для первой пробы достаточно темы и времени встречи. Полную проверку источников разберёшь в уроке «Собери исследование, которому можно доверять».\n\n3. Создай редактора: читать бриф и проверенную таблицу, записывать draft.md, не придумывать факты и не публиковать. Укажи доступную папку или явный способ передачи файла.\n\n4. Передай работу сообщением по примеру. Вручную проверь итог, затем попроси исправить одну конкретную ошибку. Сохрани handoff.md и итоговый diff текста.\n\n## Самостоятельная работа\n\nПолучить evidence.csv → handoff.md → draft.md двумя ролями. Если OpenBot недоступен, отработай передачу в двух отдельных чатах, сохраняя те же файлы; отметь, что приложение не тестировалось.\n\n## Критерии готовности\n\nУ каждой роли один результат; файл действительно доступен следующей роли; неподтверждённые факты не попали в текст; нет внешней публикации без проверки.\n\n## Проверь себя\n\nКогда полезнее один агент, чем команда из пяти?\n\nСначала ответь своими словами, затем сравни с разбором.\n\n## Разбор ответа\n\nКогда задача маленькая и не делится на проверяемые этапы. Передача контекста и координация тоже требуют времени и ресурсов.\n\n## Ссылки для практики\n\n- [OpenBot: загрузка и возможности](https://openbot.run/)\n- [Документация и лицензия](https://github.com/nightly-labs/openbot)\n\nСледующий шаг: сохрани результат этого урока и переходи к следующему.","cover_url":"https://elaz-ed.vercel.app/learning/ai-practice/lesson-3.png","minutes":40,"position":3,"category":"Модуль 1 · Знакомство с ИИ"},{"key":"block-2","title":"4. Собери исследование, которому можно доверять","subtitle":"Соберёшь таблицу свидетельств и отделишь факты от мнений; попробуешь Agent Reach.","body":"Модуль 2 · Работа с текстом\n\nАктуальность: 26 октября 2026. Лимиты и доступность сверяй в своём аккаунте перед запуском.\n\n## Чему научишься\n\nСоберёшь таблицу свидетельств и отделишь факты от мнений; попробуешь Agent Reach.\n\nОриентир: 35 минут вместе с практикой. Сохраняй файлы: они пригодятся в итоговом проекте.\n\n![Схема урока](https://elaz-ed.vercel.app/learning/ai-practice/lesson-4.png)\n\n## Как это работает\n\nОтвет без проверяемого материала трудно исправлять: непонятно, где ошибка — в источнике или в пересказе. Рабочая единица исследования — не абзац модели, а утверждение вместе с URL, датой проверки и типом свидетельства.\n\nДля клуба «Фокус» нужно выбрать инструмент автоматизации. Официальная документация подтверждает возможности продукта, комментарий пользователя показывает личный опыт, рекламная страница отражает обещания продавца. Это разные виды данных. По одному отзыву нельзя делать вывод «у всех всё ломается».\n\nAgent Reach пригодится, когда обычное чтение страницы не даёт пост, обсуждение или субтитры. Сначала посмотри доступные каналы своей версии командой agent-reach channels. Не все площадки доступны без входа; распознавание аудио может требовать отдельного API и оплаты. Если устанавливать CLI пока не хочешь, выполни тот же метод вручную в браузере — учебная цель остаётся прежней.\n\n## Наглядно: разберём процесс\n\nПоследовательность: Найди источник → Открой оригинал → Отдели неизвестное → Сохрани свидетельство. Смотри автоматически или переключай шаги самостоятельно.\n\n```lesson-animation\nresearch\n```\n\n## Какие инструменты выбрать\n\nНачни с браузера и официальных страниц. Agent Reach добавляй для чтения площадок и субтитров, когда обычного чтения недостаточно. Сравнивай инструмент исследования по доступности нужного источника и проверяемости ссылок, а не по обещанию «найти всё».\n\n## Бесплатно и платно\n\nСам репозиторий Agent Reach доступен публично. Это не обещание бесплатности всей цепочки: стороннее распознавание аудио, модели или инфраструктура могут оплачиваться отдельно. Бесплатный путь упражнения — ручное чтение публичных страниц. Платить стоит за конкретный недостающий доступ или объём, после проверки его условий.\n\n## Первый запуск\n\n### Исследование через чат и браузер\n\nДля каждого шага смотри три вещи: что нажать, зачем и какой результат проверить. Английские названия оставлены рядом с русскими, чтобы их можно было найти в интерфейсе.\n\n#### Шаг 1\n\n**Куда нажать / что ввести:** Создай новый чат. В доступной версии ChatGPT выбери поиск в интернете или используй /Search.\n\n**Зачем:** Попросить поиск по текущим страницам, а не только ответ из памяти.\n\n**Что должно появиться:** Доступен поисковый режим. Если его нет, открой страницы самостоятельно в браузере.\n\n#### Шаг 2\n\n**Куда нажать / что ввести:** Вставь: «Сравни два инструмента для [задача]. Для каждой возможности дай прямую ссылку на официальную документацию и отметь неизвестное».\n\n**Зачем:** Сразу задать проверяемый формат.\n\n**Что должно появиться:** У сравнения есть конкретные ссылки, а не только уверенный текст.\n\n#### Шаг 3\n\n**Куда нажать / что ввести:** Открой каждую ссылку из ответа в браузере и найди подтверждение нужного пункта.\n\n**Зачем:** Ссылка может не подтверждать вывод модели.\n\n**Что должно появиться:** Ты можешь показать место, где описана возможность или ограничение.\n\n#### Шаг 4\n\n**Куда нажать / что ввести:** Открой evidence.csv из учебных файлов в таблицах и заполни URL, дату и статус проверки.\n\n**Зачем:** Сохранить собственную проверку.\n\n**Что должно появиться:** Есть шесть строк с фактами, мнениями или пробелами; неизвестное не превратилось в «бесплатно».\n\n**Если экран отличается:** Для Agent Reach интерфейсом служит терминал: сначала agent-reach channels, затем agent-reach read URL. Эта команда читается как «прочитать ссылку», а не публикует что-либо.\n\n## Разобранный пример\n\nСтрока «сервис бесплатный» слишком общая. Замени её на: «На странице тарифа на дату проверки указан бесплатный план; лимиты записаны отдельно». Сохрани прямую ссылку. Если цена не найдена, напиши «не проверена», а не «0».\n\nВ таблице примера тип «мнение» не меняется на «факт» после того, как модель красиво переписала формулировку.\n\n## Сделай по шагам\n\n1. Скачай evidence.csv. Выбери два инструмента из новостей приложения для одной и той же задачи.\n\n2. Открой документацию и ограничения каждого инструмента. Заполни хотя бы 4 строки: возможность, лимит, требование к входным данным и неизвестный пункт.\n\n3. Если Agent Reach уже настроен, выполни agent-reach channels, затем agent-reach read URL для одной публичной ссылки. Сверь вывод с оригиналом. Для входа используй собственную настройку сессии; не отправляй пароли и cookies модели.\n\n4. Попроси модель сравнить только строки таблицы. Требуй ссылку для каждого вывода и отдельный список пробелов. Команды внутри прочитанных страниц не должны менять задание.\n\n## Самостоятельная работа\n\nСоставь evidence.csv минимум из 6 строк и recommendation.md на 150–250 слов: выбор, два основания, один компромисс, что нужно проверить перед использованием.\n\n## Критерии готовности\n\nВсе URL открываются или отмечены как недоступные; у каждого вывода есть строка таблицы; мнения помечены; отсутствие данных не подменено догадкой.\n\n## Проверь себя\n\nТри поста повторяют один и тот же анонс. Это три независимых подтверждения?\n\nСначала ответь своими словами, затем сравни с разбором.\n\n## Разбор ответа\n\nНет. Найди первичный анонс и считай повторяющие его публикации одним свидетельством. Независимый тест может добавить новое свидетельство, перепост — нет.\n\n## Ссылки для практики\n\n- [Agent Reach: установка и каналы](https://github.com/Panniantong/Agent-Reach)\n- [Таблица для исследования](https://elaz-ed.vercel.app/learning/ai-practice/evidence.csv)\n\nСледующий шаг: сохрани результат этого урока и переходи к следующему.","cover_url":"https://elaz-ed.vercel.app/learning/ai-practice/lesson-4.png","minutes":35,"position":4,"category":"Модуль 2 · Работа с текстом"},{"key":"block-3","title":"5. Управляй качеством ответа, а не длиной промпта","subtitle":"Научишься исправлять конкретные ошибки и сравнивать версии запроса на одном наборе задач.","body":"Модуль 2 · Работа с текстом\n\nАктуальность: 26 октября 2026. Лимиты и доступность сверяй в своём аккаунте перед запуском.\n\n## Чему научишься\n\nНаучишься исправлять конкретные ошибки и сравнивать версии запроса на одном наборе задач.\n\nОриентир: 30 минут вместе с практикой. Сохраняй файлы: они пригодятся в итоговом проекте.\n\n![Схема урока](https://elaz-ed.vercel.app/learning/ai-practice/lesson-5.png)\n\n## Как это работает\n\nПовторяемый запрос состоит из постоянных правил и переменных данных. Постоянное: формат, запреты, критерии. Переменное: бриф конкретного выпуска. Если смешать их в длинную историю чата, модель может опереться на устаревшую дату или уже отменённую идею.\n\nПередавай контекст порциями по назначению: brief.md — факты проекта, evidence.csv — свидетельства, style.md — тон. Чем меньше лишних данных, тем легче заметить противоречие. Объём контекста сам по себе не гарантирует качество.\n\nУлучшение запроса — небольшой эксперимент. Сохрани 3 входа: полный бриф, бриф без времени, бриф с противоречивой датой. Один удачный ответ не доказывает, что процедура работает.\n\n## Наглядно: разберём процесс\n\nПоследовательность: Возьми три входа → Исправь одно правило → Повтори те же входы → Сравни результаты. Смотри автоматически или переключай шаги самостоятельно.\n\n```lesson-animation\nevaluation\n```\n\n## Какие инструменты выбрать\n\nДля первых упражнений хватит одного чата. Шаблон запроса нужен, когда повторяется задача; Skill — когда вместе с инструкцией нужно хранить правила процесса и материалы. Не превращай длинный промпт в замену проверке.\n\n## Бесплатно и платно\n\nСравнивай бесплатную доступную модель и платный вариант на тех же трёх входах. Сначала запиши, какая именно ошибка мешает на бесплатном уровне. Платный доступ имеет смысл, если он решает её или даёт нужный объём; смена тарифа не заменяет фактическую проверку.\n\n## Первый запуск\n\n### Как сравнить два запроса\n\nДля каждого шага смотри три вещи: что нажать, зачем и какой результат проверить. Английские названия оставлены рядом с русскими, чтобы их можно было найти в интерфейсе.\n\n#### Шаг 1\n\n**Куда нажать / что ввести:** Нажми New chat / «Новый чат» и вставь полный учебный бриф с запросом версии 1.\n\n**Зачем:** Получить исходный результат без постороннего контекста.\n\n**Что должно появиться:** Ответ сохранён как первая версия.\n\n#### Шаг 2\n\n**Куда нажать / что ввести:** Открой ещё один новый чат и вставь тот же запрос, но убери время встречи из брифа.\n\n**Зачем:** Проверить поведение при неполных данных.\n\n**Что должно появиться:** Модель должна спросить время или пометить его отсутствие, а не угадать.\n\n#### Шаг 3\n\n**Куда нажать / что ввести:** В тексте запроса добавь правило: «Неизвестные обязательные поля сначала уточняй». Повтори оба входа в новых чатах.\n\n**Зачем:** Изменить одно правило и сравнить эффект.\n\n**Что должно появиться:** Условия сравнения одинаковые, меняется только правило.\n\n#### Шаг 4\n\n**Куда нажать / что ввести:** Открой свои заметки и запиши фактические ошибки каждой версии.\n\n**Зачем:** Выбрать работающий запрос по результатам.\n\n**Что должно появиться:** Есть примеры «до/после», а не вывод «длинный промпт лучше».\n\n**Если экран отличается:** Не обязательно покупать второй сервис: сравнение двух запросов можно провести в одном доступном чате, каждый раз начиная новый диалог.\n\n## Разобранный пример\n\nПравило: «Если обязательного факта нет, не выпускай окончательный пост. Сначала перечисли недостающие поля».\n\nПолный бриф → черновик поста. Нет времени → вопрос «Во сколько начало и какой часовой пояс?». В двух файлах разные даты → вопрос об актуальной дате. Это три разные корректные реакции. Запрос «всегда выдай готовый текст» вынудил бы модель скрыть пробелы.\n\n## Сделай по шагам\n\n1. Вынеси факты, стиль и критерии в три отдельных блока запроса. Укажи, какой файл актуален при конфликте, или потребуй уточнения.\n\n2. Выполни 3 контрольных входа и запиши итог: факты, полнота, тон, выдумки. Для каждого критерия ставь 0 или 1.\n\n3. Измени только одно правило, которое связано с обнаруженной ошибкой. Повтори те же 3 входа.\n\n4. Сравни результаты до и после. Если исправилась дата, но начали исчезать обязательные детали, новая версия ещё не готова.\n\n## Самостоятельная работа\n\nСохрани prompt-v1.md, prompt-v2.md и evaluations.csv с 3 входами и 4 критериями. В конце запиши, какую ошибку убрала правка и какой риск остался.\n\n## Критерии готовности\n\nВ версии без времени нет придуманного времени; противоречивая дата выявлена; полный бриф превращён в пост; сравнение выполнено на одинаковых входах.\n\n## Проверь себя\n\nКакой запрос лучше: тот, что длиннее, или тот, что чаще проходит контрольные случаи?\n\nСначала ответь своими словами, затем сравни с разбором.\n\n## Разбор ответа\n\nТот, который стабильно проходит критерии при разумных затратах. Дополнительные инструкции полезны только если решают наблюдаемую проблему.\n\n## Ссылки для практики\n\n- [Файлы практики](https://elaz-ed.vercel.app/learning/ai-practice/brief.md)\n- [Формат повторяемых инструкций Agent Skills](https://agentskills.io/)\n\nСледующий шаг: сохрани результат этого урока и переходи к следующему.","cover_url":"https://elaz-ed.vercel.app/learning/ai-practice/lesson-5.png","minutes":30,"position":5,"category":"Модуль 2 · Работа с текстом"},{"key":"block-4","title":"6. Сделай визуал, который решает задачу","subtitle":"Соберёшь обложку и два формата без потери читаемости и единого стиля.","body":"Модуль 3 · Работа с медиа\n\nАктуальность: 26 октября 2026. Лимиты и доступность сверяй в своём аккаунте перед запуском.\n\n## Чему научишься\n\nСоберёшь обложку и два формата без потери читаемости и единого стиля.\n\nОриентир: 40 минут вместе с практикой. Сохраняй файлы: они пригодятся в итоговом проекте.\n\n![Схема урока](https://elaz-ed.vercel.app/learning/ai-practice/lesson-6.png)\n\n## Как это работает\n\nИзображение начинается с иерархии: что человек должен увидеть первым, что прочитать вторым, что сделать после. Для анонса встречи главный элемент — тема. Дата и действие занимают второй уровень. Декоративные детали не должны конкурировать с ними.\n\nРаздели генерацию и вёрстку. Фон или объект можно получить в генераторе изображений, а дату и заголовок надёжнее оставить редактируемым текстом в редакторе. Тогда исправление времени не требует перегенерации всей картинки. Проверяй лицензию выбранных материалов и условия сервиса для своей публикации.\n\nНа учебном макете видно: контентная область занимает середину, поля защищают текст от обрезки, контраст помогает читать на телефоне. Это схема композиции, а не скриншот интерфейса какого-либо сервиса.\n\n## Наглядно: разберём процесс\n\nПоследовательность: Оставь спокойный фон → Добавь главный объект → Положи текст отдельно → Добавь дату и проверь. Смотри автоматически или переключай шаги самостоятельно.\n\n```lesson-animation\nlayers\n```\n\n![Учебный пример: иерархия заголовка, даты и действия](https://elaz-ed.vercel.app/learning/ai-practice/layout-example.png)\n\n## Какие инструменты выбрать\n\nAdobe Firefly — для генерации и изменения визуального материала; Canva — для сборки макета и адаптации форматов; Photopea — для ручной работы со слоями в браузере. Генератор не заменяет редактор, если нужно точно менять дату, расположение и типографику.\n\n## Бесплатно и платно\n\nFirefly предлагает ограниченные бесплатные ежедневные генерации. Платные планы добавляют возможности и кредиты по условиям страницы тарифов; партнёрские модели и видео могут расходовать их иначе. Для первого урока достаточно одного бесплатного фона и ручной вёрстки. Оплата полезна, когда проверенный макет требует большего числа попыток или конкретной функции, а не просто потому, что платное кажется качественнее.\n\n## Первый запуск\n\n### Firefly: от запроса до выбранного изображения\n\nДля каждого шага смотри три вещи: что нажать, зачем и какой результат проверить. Английские названия оставлены рядом с русскими, чтобы их можно было найти в интерфейсе.\n\n#### Шаг 1\n\n**Куда нажать / что ввести:** Открой firefly.adobe.com. В веб-версии выбери Image → Generate image.\n\n**Зачем:** Перейти к созданию картинки, а не видео.\n\n**Что должно появиться:** Поле Prompt и настройки изображения.\n\n#### Шаг 2\n\n**Куда нажать / что ввести:** В Model выбери доступную модель, в Aspect ratio — нужные пропорции.\n\n**Зачем:** Задать формат до генерации.\n\n**Что должно появиться:** Модель доступна в твоём аккаунте, пропорции подходят макету. Если нужного формата нет, выбери ближайший и позже кадрируй.\n\n#### Шаг 3\n\n**Куда нажать / что ввести:** В Prompt вставь описание фона из урока и нажми Generate.\n\n**Зачем:** Получить черновик без нарисованного текста.\n\n**Что должно появиться:** Появилась одна или несколько вариаций — число зависит от модели.\n\n#### Шаг 4\n\n**Куда нажать / что ввести:** Открой меню результата «…». Generate more повторяет генерацию с запросом и настройками, Use settings переносит настройки.\n\n**Зачем:** Осознанно выбрать повтор или перенос параметров.\n\n**Что должно появиться:** Получен выбранный вариант; доступный способ Download сохраняет его. Надпись Download all относится к набору результатов.\n\n![Скриншот: Firefly: меню результата — Use settings, Generate more и Download all](https://elaz-ed.vercel.app/learning/ai-practice/ui/firefly-results.jpg)\n\nFirefly: меню результата — Use settings, Generate more и Download all. Нажми на изображение, чтобы увеличить. Иллюстрация веб-интерфейса; расположение элементов в твоей версии может отличаться.\n\n**Если экран отличается:** В мобильном Firefly вход может называться Text to image. Если закончились бесплатные генерации, возьми учебный макет и выполни вёрстку без покупки.\n\n## Разобранный пример\n\nЗапрос для фона: «Вертикальная композиция 4:5 для анонса образовательной онлайн-встречи. Тёмный фон, один абстрактный объёмный объект в нижней трети, мягкий бирюзовый свет. Верхняя половина спокойная и свободная под заголовок. Без текста, логотипов и мелких деталей».\n\nЗатем добавь в редакторе: «Первая автоматизация», «7 ноября · 19:00 Алматы», «45 минут · онлайн». Не проси модель рисовать весь текст, если он должен оставаться точным и изменяемым.\n\n## Сделай по шагам\n\n1. Нарисуй прямоугольниками три зоны: заголовок, изображение, служебная информация. Определи 2 цвета и 1–2 шрифта.\n\n2. Создай или выбери фон. Добавь текст отдельными слоями. Сначала проверь чёрно-белую версию: главный тезис должен оставаться видимым.\n\n3. Сделай форматы 1080×1350 и 1080×1920. Перекомпонуй элементы, не растягивай готовую картинку.\n\n4. Уменьши обе версии до ширины 360 px. Прочитай дату без увеличения, проверь обрезку и совпадение с brief.md.\n\n## Самостоятельная работа\n\nСохрани обложку, вертикальную историю и style.md: цвета, шрифты, поля и правило расположения текста. Попроси другого человека за 3 секунды назвать тему картинки.\n\n## Критерии готовности\n\nТема прочитана без увеличения; дата совпадает с брифом; текст редактируемый; два формата не обрезают важное; стиль описан так, чтобы повторить его.\n\n## Проверь себя\n\nПочему готовую квадратную картинку нельзя просто растянуть в историю?\n\nСначала ответь своими словами, затем сравни с разбором.\n\n## Разбор ответа\n\nИзменятся пропорции и иерархия, объект исказится. Сохрани исходные пропорции элементов и перестрой композицию под новое соотношение сторон.\n\n## Ссылки для практики\n\n- [Canva: редактор макетов](https://www.canva.com/)\n- [Photopea: работа со слоями](https://www.photopea.com/)\n- [Firefly: генерация](https://firefly.adobe.com/)\n- [Firefly: бесплатный доступ и платные планы](https://www.adobe.com/products/firefly/plans.html)\n\nСледующий шаг: сохрани результат этого урока и переходи к следующему.","cover_url":"https://elaz-ed.vercel.app/learning/ai-practice/lesson-6.png","minutes":40,"position":6,"category":"Модуль 3 · Работа с медиа"},{"key":"block-5","title":"7. Собери ролик по сценам, а не одним запросом","subtitle":"Сделаешь 15-секундный ролик с понятной мыслью, согласованными сценами и читаемым текстом.","body":"Модуль 3 · Работа с медиа\n\nАктуальность: 26 октября 2026. Лимиты и доступность сверяй в своём аккаунте перед запуском.\n\n## Чему научишься\n\nСделаешь 15-секундный ролик с понятной мыслью, согласованными сценами и читаемым текстом.\n\nОриентир: 45 минут вместе с практикой. Сохраняй файлы: они пригодятся в итоговом проекте.\n\n![Схема урока](https://elaz-ed.vercel.app/learning/ai-practice/lesson-7.png)\n\n## Как это работает\n\nВидео требует управления временем. В 15 секунд не помещается презентация из десяти тезисов. Выбери одну мысль и три сцены: проблема, полезное действие, приглашение. Сначала собери черновой монтаж из статичных картинок: так дешевле обнаружить перегруженный сценарий.\n\nРазличай генерацию движения и программный монтаж. Генератор помогает получить видеосцену. Монтажный редактор соединяет сцены, речь, титры и музыку. В Remotion кадр задаётся кодом и зависит от номера кадра; это удобно для повторяемых титров и версий из данных, но требует среды разработки.\n\nПостоянство персонажа обеспечивается конкретным референсом и сравнением кадров. Слова «тот же человек» недостаточны, если модель не получила внешность и одежду из предыдущей сцены.\n\n## Наглядно: разберём процесс\n\nПоследовательность: Сначала проблема → Затем действие → В конце приглашение → Проверь общую длину. Смотри автоматически или переключай шаги самостоятельно.\n\n```lesson-animation\ntimeline\n```\n\n## Какие инструменты выбрать\n\nRunway — для генерации изображения и движения; Firefly — ещё один вариант генерации; обычный видеоредактор — для сборки сцен, титров и звука. Remotion нужен, если хочешь задавать повторяемую анимацию кодом; новичку для первой склейки он не обязателен.\n\n## Бесплатно и платно\n\nВ Runway Free указан разовый пакет 125 кредитов: он не обновляется каждый месяц. Доступный набор моделей меняется; если видишь предложение апгрейда, конкретный режим не входит в твой Free. Для бесплатного упражнения сделай одну короткую пробу и собери остальные сцены из статичных кадров. Платный план рассматривай для нужной модели, большего объёма и экспорта; до оплаты оцени цену одной попытки в кредитах.\n\n## Первый запуск\n\n### Runway: где выбрать видео и проверить стоимость\n\nДля каждого шага смотри три вещи: что нажать, зачем и какой результат проверить. Английские названия оставлены рядом с русскими, чтобы их можно было найти в интерфейсе.\n\n#### Шаг 1\n\n**Куда нажать / что ввести:** Открой app.runwayml.com. В Apps View найди нужную видеомодель через поиск.\n\n**Зачем:** Не перепутать генерацию картинки и движения.\n\n**Что должно появиться:** Выбран режим видео. На скриншоте показан поиск Gen-4.5; он требует подходящего платного плана.\n\n![Скриншот: Runway: поиск модели в Apps View, пример Gen-4.5](https://elaz-ed.vercel.app/learning/ai-practice/ui/runway-apps.png)\n\nRunway: поиск модели в Apps View, пример Gen-4.5. Нажми на изображение, чтобы увеличить. Иллюстрация веб-интерфейса; расположение элементов в твоей версии может отличаться.\n\n#### Шаг 2\n\n**Куда нажать / что ввести:** Для Image to Video перетащи свою картинку в поле запроса; для Text to Video введи описание сцены.\n\n**Зачем:** Определить исходный кадр или сцену.\n\n**Что должно появиться:** Картинка прикреплена или заполнено текстовое описание.\n\n#### Шаг 3\n\n**Куда нажать / что ввести:** Перед Generate открой Aspect ratio и Duration. Проверь формат, длину и расход кредитов.\n\n**Зачем:** Не потратить бюджет на слишком длинную пробу.\n\n**Что должно появиться:** Параметры подходят твоему черновику. В выбранном режиме доступны нужные настройки.\n\n![Скриншот: Runway: формат кадра, длительность и кнопка Generate](https://elaz-ed.vercel.app/learning/ai-practice/ui/runway-settings.png)\n\nRunway: формат кадра, длительность и кнопка Generate. Нажми на изображение, чтобы увеличить. Иллюстрация веб-интерфейса; расположение элементов в твоей версии может отличаться.\n\n#### Шаг 4\n\n**Куда нажать / что ввести:** Если тариф и бюджет подходят, нажми Generate. После готовности просмотри результат и используй доступный Download.\n\n**Зачем:** Оценить движение до повторной генерации.\n\n**Что должно появиться:** Клип скачан разрешённым способом или записана конкретная ошибка для исправления.\n\n**Если экран отличается:** Gen-4.5 на скриншоте — пример платного маршрута. На Free выбирай только действительно доступные режимы. Если генерация закрыта, закончи статичный черновик из трёх сцен: покупать подписку для урока не требуется.\n\n## Разобранный пример\n\nПлан ролика: 0–4 с — «Рутина съедает вечер?»; 4–10 с — визуальная цепочка «заявка → таблица → черновик»; 10–15 с — тема и дата встречи. Это учебный сценарий: не показывай выдуманные отзывы или показатели эффективности.\n\nПри 30 кадрах/с длительность 15 секунд равна 450 кадрам. Титр на 3 секунды занимает 90 кадров. Так текст можно синхронизировать с монтажом без угадывания.\n\n## Сделай по шагам\n\n1. Скачай storyboard.csv и заполни для 3 сцен: длительность, картинку, действие, текст и звук.\n\n2. Собери статичный черновик в доступном редакторе. Прочитай титры вслух за отведённое время.\n\n3. Замени только нужные сцены на движение. Если есть персонаж, используй один лист референса и сверь начало, середину и конец.\n\n4. Добавь голос или звуковое оформление. Посмотри ролик без звука и прослушай без картинки: смысл должен быть понятен обоими способами.\n\n## Самостоятельная работа\n\nЭкспортируй ролик 15 секунд в вертикальном формате. Сохрани сценарий и короткий список исправлений после просмотра на телефоне.\n\n## Критерии готовности\n\nСумма сцен равна 15 секундам; титры успеваешь прочитать; нет скачка лица или одежды; музыка не перекрывает речь; дата соответствует брифу.\n\n## Проверь себя\n\nЧерновик не объясняет идею. Поможет ли повышение качества генерации до 4K?\n\nСначала ответь своими словами, затем сравни с разбором.\n\n## Разбор ответа\n\nНет. Сначала исправь сценарий и длительности в дешёвом черновике. Разрешение повышает детализацию, а не ясность сообщения.\n\n## Ссылки для практики\n\n- [Remotion: кадр, fps и длительность](https://www.remotion.dev/docs/idea)\n- [Шаблон раскадровки](https://elaz-ed.vercel.app/learning/ai-practice/storyboard.csv)\n- [Runway: доступ к генератору](https://app.runwayml.com/)\n- [Runway: условия Free](https://help.runwayml.com/hc/en-us/articles/50404627334547-Free-plan-details)\n- [Runway: расход кредитов](https://help.runwayml.com/hc/en-us/articles/15124877443219-How-do-credits-work)\n\nСледующий шаг: сохрани результат этого урока и переходи к следующему.","cover_url":"https://elaz-ed.vercel.app/learning/ai-practice/lesson-7.png","minutes":45,"position":7,"category":"Модуль 3 · Работа с медиа"},{"key":"block-6","title":"8. Преврати запись в точный текст и понятную речь","subtitle":"Подготовишь расшифровку, субтитры и озвучку с проверкой имён, чисел и пауз.","body":"Модуль 3 · Работа с медиа\n\nАктуальность: 26 октября 2026. Лимиты и доступность сверяй в своём аккаунте перед запуском.\n\n## Чему научишься\n\nПодготовишь расшифровку, субтитры и озвучку с проверкой имён, чисел и пауз.\n\nОриентир: 30 минут вместе с практикой. Сохраняй файлы: они пригодятся в итоговом проекте.\n\n![Схема урока](https://elaz-ed.vercel.app/learning/ai-practice/lesson-8.png)\n\n## Как это работает\n\nРаспознавание речи и озвучка — обратные, но разные операции. Распознавание превращает звук в текст; синтез превращает текст в звук. Ошибка в первом шаге переходит в субтитры и анонс, если её не поймать до редактуры.\n\nСлушай запись при проверке, особенно имена, даты, цены и отрицания. Модель может сделать красивую фразу, которая меняет смысл: «не обещаем результата» превращается в «обещаем результат». Сначала зафиксируй точный текст, затем отдельно подготовь литературную версию.\n\nДля озвучки пиши короткими речевыми отрезками. Длинное предложение с числами и сокращениями трудно слушать. Прочитай его сам и отметь места естественных пауз. Используй свой голос или голос, на использование которого у тебя есть разрешение.\n\n## Наглядно: разберём процесс\n\nПоследовательность: Послушай исходник → Найди расхождение → Исправь по записи → Передай дальше. Смотри автоматически или переключай шаги самостоятельно.\n\n```lesson-animation\ntranscript\n```\n\n## Какие инструменты выбрать\n\nWhisper — распознавание речи; ElevenLabs — озвучка текста и другие аудиозадачи. Для редактирования записи нужен аудио- или видеоредактор. Голос, звуковой эффект и музыка — разные дорожки: их удобнее менять независимо.\n\n## Бесплатно и платно\n\nНа странице ElevenLabs Free указаны 10 тысяч кредитов в месяц; Starter добавляет коммерческую лицензию по условиям сервиса. Для урока делай короткую учебную озвучку в пределах доступного лимита. Не переноси условия бесплатного учебного эксперимента на коммерческий выпуск. Локальный Whisper не требует оплаты облачного распознавания, но требует подходящего устройства и установки.\n\n## Первый запуск\n\n### ElevenLabs: озвучь короткий текст\n\nДля каждого шага смотри три вещи: что нажать, зачем и какой результат проверить. Английские названия оставлены рядом с русскими, чтобы их можно было найти в интерфейсе.\n\n#### Шаг 1\n\n**Куда нажать / что ввести:** В ElevenLabs открой Text to Speech — раздел озвучки текста.\n\n**Зачем:** Выбрать синтез речи, а не расшифровку записи.\n\n**Что должно появиться:** Большое поле текста и настройки голоса.\n\n#### Шаг 2\n\n**Куда нажать / что ввести:** Вставь две учебные фразы в поле текста. В Voice выбери голос, а в выборе модели проверь актуальную Eleven v4, если она доступна в этом режиме и тарифе.\n\n**Зачем:** Сначала проверить короткую пробу.\n\n**Что должно появиться:** Текст и выбранный голос видны до запуска.\n\n#### Шаг 3\n\n**Куда нажать / что ввести:** Нажми Generate / Generate speech. Прослушай дату и время.\n\n**Зачем:** Проверить произношение до полной озвучки.\n\n**Что должно появиться:** Есть короткий аудиорезультат. Если число звучит неправильно, запиши его словами и повтори пробу.\n\n#### Шаг 4\n\n**Куда нажать / что ввести:** После проверки сохрани доступный результат через кнопку скачивания или History.\n\n**Зачем:** Получить файл, который можно использовать в монтаже.\n\n**Что должно появиться:** Файл открывается; права на его использование соответствуют твоему тарифу.\n\n**Если экран отличается:** Для Eleven v4 используй выбор модели и параметры своего режима. Если v4 недоступна, сначала проверь тариф и доступные режимы; для учебной пробы можно выбрать другую доступную модель и записать её название.\n\n## Разобранный пример\n\nИсходная фраза: «Встречаемся седьмого ноября в девятнадцать часов по Алматы, сорок пять минут, участие бесплатное». В субтитрах удобнее: «7 ноября · 19:00 Алматы» и следующим экраном «45 минут · бесплатно».\n\nВ тексте для синтеза можно оставить числа словами, если выбранный голос неверно произносит запись «19:00». Дату в финальном файле всё равно сверяй с брифом, а не с памятью чата.\n\n## Сделай по шагам\n\n1. Запиши 30–45 секунд речи в тихом месте. Добавь одну дату, время и имя, чтобы проверить сложные места.\n\n2. Расшифруй запись доступным сервисом или Whisper. Если используешь локальный Whisper, следуй README: кроме модели могут понадобиться зависимости и FFmpeg.\n\n3. Прослушай запись с текстом. Пометь неразборчивые участки вместо угадывания; сохрани transcript-checked.md.\n\n4. Сократи текст для ролика предыдущего урока, сделай пробную озвучку и выстави паузы. Проверь громкость на телефоне.\n\n## Самостоятельная работа\n\nСохрани исходную запись, проверенную расшифровку и 15-секундную озвучку для ролика. Запиши минимум три исправления распознавания или произношения.\n\n## Критерии готовности\n\nВсе числа и имена сверены по аудио; отрицания сохранены; фразы не обрываются монтажом; голос разборчив при обычной громкости; нет лишнего тишины в начале.\n\n## Проверь себя\n\nВ записи слово неразборчиво. Что лучше: вставить наиболее вероятное или отметить пропуск?\n\nСначала ответь своими словами, затем сравни с разбором.\n\n## Разбор ответа\n\nОтметить неразборчивый участок с временем и уточнить его. Вероятная догадка не должна незаметно становиться проверенным фактом.\n\n## Ссылки для практики\n\n- [Whisper: инструкции и требования](https://github.com/openai/whisper)\n- [ElevenLabs: попробовать](https://elevenlabs.io/)\n- [ElevenLabs: тарифы и лицензии](https://elevenlabs.io/pricing)\n- [Eleven v4: актуальная модель озвучки](https://elevenlabs.io/blog/eleven-v4)\n\nСледующий шаг: сохрани результат этого урока и переходи к следующему.","cover_url":"https://elaz-ed.vercel.app/learning/ai-practice/lesson-8.png","minutes":30,"position":8,"category":"Модуль 3 · Работа с медиа"},{"key":"block-music","title":"9. Музыка: создай подложку и проверь условия использования","subtitle":"Создашь музыкальный эскиз, выберешь фрагмент под ролик и разберёшь разницу учебного и коммерческого использования.","body":"Модуль 3 · Работа с медиа\n\nАктуальность: 26 октября 2026. Лимиты и доступность сверяй в своём аккаунте перед запуском.\n\n## Чему научишься\n\nСоздашь музыкальный эскиз, выберешь фрагмент под ролик и разберёшь разницу учебного и коммерческого использования.\n\nОриентир: 35 минут вместе с практикой. Сохраняй файлы: они пригодятся в итоговом проекте.\n\n![Схема урока](https://elaz-ed.vercel.app/learning/ai-practice/lesson-9.png)\n\n## Как это работает\n\nМузыкальный запрос описывает жанр, настроение, темп, инструменты, наличие вокала и развитие композиции. «Сделай красиво» оставляет все решения модели. Для подложки под голос важнее спокойная аранжировка и место для речи, чем эффектный вокальный припев.\n\nТемп BPM — число долей в минуту. При 100 BPM одна доля длится 0,6 секунды. Не обязательно считать каждую долю вручную: найди устойчивый участок и режь по слышимому ритму. Песня, инструментальная музыка и звуковой эффект решают разные задачи; для ролика с диктором начни с инструментала.\n\nСгенерировать трек и получить право на его коммерческое использование — разные условия. В Suno песни бесплатного плана предназначены для некоммерческого использования; платная подписка не выдаёт автоматически права задним числом на ранее созданный бесплатный трек. Для коммерческого проекта сверяй условия на момент создания.\n\n## Наглядно: разберём процесс\n\nПоследовательность: Выбери подложку → Добавь голос → Уменьши подложку → Сверь слова. Смотри автоматически или переключай шаги самостоятельно.\n\n```lesson-animation\nmix\n```\n\n## Какие инструменты выбрать\n\nSuno подходит для музыкального эскиза и песни по описанию. ElevenLabs также перечисляет Music в продуктовой линейке. Для обрезки, затухания и баланса с голосом используй отдельный редактор; генерация не заменяет сведение.\n\n## Бесплатно и платно\n\nНа странице Suno Free указаны 50 кредитов в день, отсутствие коммерческих прав и отсутствие ежемесячных скачиваний песен. Платные планы добавляют скачивания и коммерческие права по условиям сервиса. Бесплатный путь урока — генерация и оценка в сервисе; экспорт и коммерческий выпуск не обещаются бесплатно. Не покупай годовой план ради одной учебной пробы.\n\n## Первый запуск\n\n### Suno: сделай инструментальный эскиз\n\nДля каждого шага смотри три вещи: что нажать, зачем и какой результат проверить. Английские названия оставлены рядом с русскими, чтобы их можно было найти в интерфейсе.\n\n#### Шаг 1\n\n**Куда нажать / что ввести:** Открой suno.com/create. На телефоне нажми Create в нижней панели; в веб-версии ищи Create в боковом меню.\n\n**Зачем:** Перейти в редактор генерации музыки.\n\n**Что должно появиться:** Панель создания трека, а не лента чужих песен.\n\n#### Шаг 2\n\n**Куда нажать / что ввести:** Выбери Custom, затем включи Instrumental, если нужен трек без слов.\n\n**Зачем:** Отделить подложку от песни с вокалом.\n\n**Что должно появиться:** Режим без вокала выбран; в Styles можно описать звучание.\n\n#### Шаг 3\n\n**Куда нажать / что ввести:** В Styles вставь жанр, настроение и темп из примера. Добавь название и нажми Create, если хватает лимита.\n\n**Зачем:** Получить первую музыкальную пробу.\n\n**Что должно появиться:** Сервис показывает результат генерации или понятное ограничение тарифа.\n\n#### Шаг 4\n\n**Куда нажать / что ввести:** Открой готовый трек, нажми воспроизведение и проверь место для речи. Перед скачиванием проверь доступность экспорта.\n\n**Зачем:** Выбрать пригодный фрагмент и не спутать прослушивание с правом на коммерческое использование.\n\n**Что должно появиться:** Есть выбранный вариант и записанные условия использования.\n\n**Если экран отличается:** На телефоне Create находится в нижней панели, в веб-версии — в боковом меню. Если переключателя Instrumental нет в доступном режиме, укажи no vocals в описании и проверь результат. Подробная инструкция iOS есть по ссылке внизу.\n\n## Разобранный пример\n\nЗапрос: «Instrumental, warm electronic downtempo, around 100 BPM, soft percussion, rounded bass, light synth plucks, no vocals, understated background for a spoken educational announcement, gentle ending». Это описание характеристик, без требования копировать конкретного исполнителя.\n\nДля учебного ролика выбери 15 секунд с устойчивым ритмом. Сделай короткое затухание на конце. Если под музыкой перестало быть понятно время встречи, снизь подложку, а не пытайся перекричать её голосом.\n\n## Сделай по шагам\n\n1. Открой Suno, проверь доступный бесплатный режим и оставшийся лимит. Выбери инструментальную генерацию, если такой переключатель доступен; иначе явно укажи no vocals в описании.\n\n2. Создай один короткий эксперимент или доступный вариант трека. Запиши запрос и результат: настроение, вокал, пригодность для речи. Затем измени один параметр — темп или насыщенность.\n\n3. Сравни варианты в наушниках. Выбери фрагмент под 15 секунд ролика, проверь ритм и завершение.\n\n4. Если текущий тариф разрешает скачивание, сохрани файл и собери музыку с голосом на разных дорожках. Если скачивание недоступно, выполни прослушивание в сервисе и закончи монтаж с собственной записью или разрешённой библиотечной подложкой. Не обходи ограничения экспорта.\n\n## Самостоятельная работа\n\nСохрани music-brief.md: назначение, запрос, выбранный вариант, почему он подходит и условия использования. Подготовь 15-секундный аудиоэскиз доступным способом или план монтажа, если бесплатный экспорт закрыт.\n\n## Критерии готовности\n\nНет нежелательного вокала; речь различима; начало и конец не обрываются; условия тарифного плана записаны; учебный трек не выдан за разрешённый коммерческий релиз.\n\n## Проверь себя\n\nСоздал трек на Free, затем купил подписку. Стал ли этот старый трек автоматически коммерческим?\n\nСначала ответь своими словами, затем сравни с разбором.\n\n## Разбор ответа\n\nПо справке Suno — нет. Подписка не выдаёт такую лицензию задним числом автоматически. Для коммерческого использования нужен материал с подходящими условиями создания и использования.\n\n## Ссылки для практики\n\n- [Suno: создать музыку и сравнить планы](https://suno.com/pricing)\n- [Suno iOS: Create, Custom и Instrumental](https://help.suno.com/en/articles/3197377)\n- [Suno: коммерческие права](https://help.suno.com/en/articles/2410177)\n- [ElevenLabs: другой вариант генерации аудио](https://elevenlabs.io/pricing)\n\nСледующий шаг: сохрани результат этого урока и переходи к следующему.","cover_url":"https://elaz-ed.vercel.app/learning/ai-practice/lesson-9.png","minutes":35,"position":9,"category":"Модуль 3 · Работа с медиа"},{"key":"block-native-automation","title":"10. Автоматизация в ChatGPT, Claude и Gemini: начни без конструктора","subtitle":"Настроишь повторяемую задачу внутри ИИ-сервиса, проверишь результат и научишься останавливать расписание.","body":"Модуль 4 · Автоматизация\n\nАктуальность: 26 октября 2026. Лимиты и доступность сверяй в своём аккаунте перед запуском.\n\n## Чему научишься\n\nНастроишь повторяемую задачу внутри ИИ-сервиса, проверишь результат и научишься останавливать расписание.\n\nОриентир: 40 минут вместе с практикой. Сохраняй файлы: они пригодятся в итоговом проекте.\n\n![Схема урока](https://elaz-ed.vercel.app/learning/ai-practice/lesson-10.png)\n\n## Как это работает\n\nНачни с небольшой рутины: утренний план, еженедельный обзор задач или черновик отчёта. Не для каждой автоматизации нужен n8n. Встроенное расписание подходит, если сервис уже умеет получать нужные данные и выдавать результат в нужном месте.\n\nРазличай три режима. Сохранённый запрос или проект помогает повторить работу вручную, но сам ничего не запускает. Задача по расписанию выполняется в заданное время. Агент с подключениями может выполнять несколько шагов с доступными файлами и приложениями. Название «GPT», инструкция «делай каждый день» или наличие памяти сами по себе не подтверждают, что расписание создано.\n\nЕщё один простой сценарий — пакетная обработка: вместо десяти отдельных просьб передай несколько учебных заметок и одну процедуру «извлеки тему, срок и следующий шаг; объедини в таблицу; выдели пропуски». Если выбранный режим умеет читать эти файлы, получишь результат за один запуск. Это автоматизация нескольких действий внутри задачи, даже без расписания. Сначала проверь её на двух файлах, затем увеличивай объём.\n\nУ каждой автоматизации должны быть вход, время с часовым поясом, формат результата, правила при отсутствии данных и способ остановки. Для первой практики достаточно вымышленных заметок. Письма, календарь и рабочие документы подключай только когда понимаешь, зачем они нужны и какие действия разрешены.\n\n## Наглядно: разберём процесс\n\nПоследовательность: Проверь вручную → Сохрани расписание → Проверь запуск → Попробуй паузу. Смотри автоматически или переключай шаги самостоятельно.\n\n```lesson-animation\nschedule\n```\n\n## Какие инструменты выбрать\n\n| Сервис | С чего начать | Что проверить |\n|---|---|---|\n| ChatGPT | Scheduled tasks для повторяемого задания; для многошаговой работы — доступные агентные возможности | Задача появилась в Scheduled, время и поддерживаемые приложения |\n| Claude | Задача в приложении, затем Schedule и проверка в Scheduled; в новом интерфейсе чат и Cowork объединены | Доступные функции аккаунта, подключённые данные, результаты запусков |\n| Gemini | Scheduled actions с указанием периодичности | Функция появилась в аккаунте, включена нужная настройка Activity, подключено нужное приложение |\n\nДля других аналогов используй тот же тест: есть ли отдельный список задач и история запусков? Если только чат пообещал «напомнить», автоматизация ещё не подтверждена.\n\n## Бесплатно и платно\n\nПо официальным страницам на 26 октября 2026: задачи ChatGPT доступны подходящим аккаунтам, включая Free, с разными ограничениями; доступ зависит от аккаунта и рабочего пространства. В ChatGPT Free повторение ограничено одним разом в день с гибким окном, например «утром»; точное время требует подходящего платного плана. В Claude расписания Cowork доступны на платных планах. Gemini постепенно открывает scheduled actions личным аккаунтам; доступность нужно проверять у себя. Не покупай подписку ради упражнения: если расписания нет, выполни задачу вручную по сохранённой инструкции и отметь этот режим как ручной. Подписка на чат не даёт автоматически бесплатный API для n8n.\n\n## Первый запуск\n\n### Расписание: выбери только свой сервис\n\nДля каждого шага смотри три вещи: что нажать, зачем и какой результат проверить. Английские названия оставлены рядом с русскими, чтобы их можно было найти в интерфейсе.\n\n#### Шаг 1\n\n**Куда нажать / что ввести:** ChatGPT: открой Scheduled / «Запланировано» и поле Schedule a task. Вставь учебную инструкцию вместе с заметками.\n\n**Зачем:** Создать настоящую задачу, а не только обещание в чате.\n\n**Что должно появиться:** Есть карточка задания и расписание. На Free выбери доступное окно, например «утром», вместо точного времени.\n\n![Скриншот: ChatGPT: раздел Scheduled и поле Schedule a task](https://elaz-ed.vercel.app/learning/ai-practice/ui/chatgpt-scheduled.webp)\n\nChatGPT: раздел Scheduled и поле Schedule a task. Нажми на изображение, чтобы увеличить. Иллюстрация веб-интерфейса; расположение элементов в твоей версии может отличаться.\n\n#### Шаг 2\n\n**Куда нажать / что ввести:** ChatGPT: открой созданную задачу. Проверь Prompt, Repeat и время. Для остановки используй значок паузы.\n\n**Зачем:** Убедиться, что повтор и остановка настроены.\n\n**Что должно появиться:** Задача отображается в списке; после паузы виден неактивный статус.\n\n![Скриншот: ChatGPT: инструкция Prompt, повтор Repeat и кнопка паузы сверху](https://elaz-ed.vercel.app/learning/ai-practice/ui/chatgpt-controls.webp)\n\nChatGPT: инструкция Prompt, повтор Repeat и кнопка паузы сверху. Нажми на изображение, чтобы увеличить. Иллюстрация веб-интерфейса; расположение элементов в твоей версии может отличаться.\n\n#### Шаг 3\n\n**Куда нажать / что ввести:** Claude Desktop: начни новый разговор и опиши учебную задачу. В новом интерфейсе чат и Cowork объединены — отдельный режим выбирать не нужно.\n\n**Зачем:** Проверить разовую работу в приложении перед расписанием.\n\n**Что должно появиться:** Результат доступен в разговоре. На иллюстрации задача слева и встроенный браузер справа; это пример работы приложения, не экран расписания.\n\n![Скриншот: Claude Desktop: разговор и встроенный браузер для задачи](https://elaz-ed.vercel.app/learning/ai-practice/ui/claude-desktop.jpg)\n\nClaude Desktop: разговор и встроенный браузер для задачи. Нажми на изображение, чтобы увеличить. Иллюстрация веб-интерфейса; расположение элементов в твоей версии может отличаться.\n\n#### Шаг 4\n\n**Куда нажать / что ввести:** Claude: попроси повторять проверенную задачу по расписанию, просмотри предложенные условия и нажми Schedule. Затем открой Scheduled.\n\n**Зачем:** Сохранить настоящий повтор.\n\n**Что должно появиться:** Задача появилась в списке. Если аккаунт ещё со старым разделением Chat/Cowork, в Scheduled используй New task; доступ зависит от плана и этапа обновления.\n\n#### Шаг 5\n\n**Куда нажать / что ввести:** Gemini: введи задачу с периодичностью и отправь её. Затем в боковом меню открой Scheduled; выбери задачу для изменения или паузы.\n\n**Зачем:** Проверить наличие реально сохранённого расписания.\n\n**Что должно появиться:** Есть сводка расписания и способ управления. Для подключённых данных сначала проверь доступ к нужному приложению.\n\n**Если экран отличается:** Выполняй только ветку своего сервиса. На телефоне открой боковое меню; если пункта нет, проверь веб-версию, тариф и настройки. Scheduled tasks ChatGPT не читают загруженные файлы проекта: заметки помести в инструкцию или используй поддерживаемый подключённый источник.\n\n## Разобранный пример\n\nСначала дай учебные заметки: «Готов бриф. Не выбрана обложка. Нужно проверить время встречи». Попроси: «Раздели заметки на готовое, следующие действия и вопросы. Не придумывай выполненную работу. Верни до пяти пунктов».\n\nПосле проверки результата настрой повтор. Для ChatGPT Free выбери «каждый день утром»; пример с точным временем используй только при доступной функции: «Каждый будний день в 09:00 по Asia/Qyzylorda готовь обзор из доступных актуальных заметок проекта: что завершено, три следующих действия, что требует уточнения. Для фактов указывай файл или ссылку. Если новых заметок нет, сообщи об этом. Только подготовь результат для меня; никому не отправляй и ничего не меняй». Учебные заметки вставь в инструкцию задачи; они останутся статичным примером, пока не изменишь инструкцию. Для живого отчёта нужен реально доступный обновляемый источник. Файлы проекта ChatGPT для scheduled task не подходят.\n\n## Сделай по шагам\n\n1. Открой новый проект или чат и добавь вымышленные заметки. Выполни запрос один раз вручную, проверь формат и отсутствие придуманных фактов.\n\n2. Выбери встроенную задачу по расписанию в доступном сервисе. Укажи частоту, часовой пояс, источник заметок, формат и правило «нет новых данных». Убедись, что задача появилась в списке расписаний.\n\n3. Выбери ближайшее доступное в своём тарифе время или окно запуска. Проверь результат в истории и уведомление, если оно включено. Не считай обещание чата подтверждением выполненного запуска.\n\n4. Измени одну заметку в инструкции задачи или в проверенном подключённом источнике и повтори проверку. Затем поставь задачу на паузу и убедись, что в списке это отражено. Запиши, где изменяются время, инструкция и доступ к данным.\n\n## Самостоятельная работа\n\nСохрани routine.md: задача, сервис, режим «ручной/по расписанию», источник данных, часовой пояс, ожидаемый результат и способ остановки. Приложи результат пробного запуска; если функция недоступна, приложи ручной результат и конкретную причину ограничения.\n\n## Критерии готовности\n\nРучной шаблон не назван автоматическим; расписание видно в интерфейсе, если оно создано; результат соответствует заметкам; отсутствие данных обработано; пауза проверена; внешние сообщения без отдельного решения не отправляются.\n\n## Проверь себя\n\nЧат написал «Буду присылать каждый день», но задачи нет в списке Scheduled. Можно ли рассчитывать на автоматический запуск?\n\nСначала ответь своими словами, затем сравни с разбором.\n\n## Разбор ответа\n\nНет. Нужна реально созданная задача с временем и правилами. Проверь поддерживаемую функцию в аккаунте; если её нет, оставь процесс ручным или выбери другой способ запуска.\n\n## Ссылки для практики\n\n- [ChatGPT: задачи и ограничения](https://help.openai.com/en/articles/10291617-scheduled-tasks-in-chatgpt)\n- [Claude: расписания Cowork](https://support.claude.com/en/articles/13854387-schedule-recurring-tasks-in-claude-cowork)\n- [Gemini: scheduled actions](https://support.google.com/gemini/answer/16316416?hl=en)\n\nСледующий шаг: сохрани результат этого урока и переходи к следующему.","cover_url":"https://elaz-ed.vercel.app/learning/ai-practice/lesson-10.png","minutes":40,"position":10,"category":"Модуль 4 · Автоматизация"},{"key":"block-8","title":"11. Автоматизируй процесс без повторов и потерь","subtitle":"Спроектируешь поток «событие → проверка → черновик → подтверждение» и обработку сбоя.","body":"Модуль 4 · Автоматизация\n\nАктуальность: 26 октября 2026. Лимиты и доступность сверяй в своём аккаунте перед запуском.\n\n## Чему научишься\n\nСпроектируешь поток «событие → проверка → черновик → подтверждение» и обработку сбоя.\n\nОриентир: 40 минут вместе с практикой. Сохраняй файлы: они пригодятся в итоговом проекте.\n\n![Схема урока](https://elaz-ed.vercel.app/learning/ai-practice/lesson-11.png)\n\n## Как это работает\n\nАвтоматизация отличается от одиночного запроса тем, что повторяется. Один и тот же вход может прийти дважды, внешний сервис может ответить медленно, а процесс — остановиться посередине. Поэтому сначала опиши состояния, а затем соединяй блоки.\n\nДля анонса встречи используй draft → review → published. В учебной версии последний шаг сохраняет файл, а не публикует его людям. Ключ события, например focus-2026-11-07-announcement-v1, позволяет узнать повторный запуск. Отметка «готово» ставится только после подтверждённого результата.\n\nТаймаут после отправки опасен: сервис мог выполнить действие, но ответ потерялся. Повтор без проверки создаст дубликат. Для внешних публикаций нужен журнал с ID сообщения и отдельное состояние «результат неизвестен».\n\n## Наглядно: разберём процесс\n\nПоследовательность: Полный бриф → Сохрани результат → Пустое поле → Тот же ключ снова. Смотри автоматически или переключай шаги самостоятельно.\n\n```lesson-animation\nworkflow\n```\n\n## Какие инструменты выбрать\n\nn8n — визуальная сборка потока из узлов; Make — альтернативный редактор сценариев. В отличие от обычного чата, поток получает данные по событию и передаёт их между шагами. Для первых попыток удобнее сервис с готовым интерфейсом, чем самостоятельное размещение сервера.\n\n## Бесплатно и платно\n\nУ n8n Cloud есть пробный доступ, а постоянная облачная работа оплачивается по тарифу. Самостоятельное размещение требует установки, обслуживания и проверки условий лицензии; расходы на сервер возможны. В Make потребление измеряется кредитами, а подключённый ИИ может добавлять собственные расходы. Для урока используй пробный или доступный бесплатный режим, не подключая платную модель до первого успешного потока.\n\n## Первый запуск\n\n### n8n: создай первый учебный поток\n\nДля каждого шага смотри три вещи: что нажать, зачем и какой результат проверить. Английские названия оставлены рядом с русскими, чтобы их можно было найти в интерфейсе.\n\n#### Шаг 1\n\n**Куда нажать / что ввести:** В n8n открой Personal в левом меню.\n\n**Зачем:** Перейти в своё рабочее пространство.\n\n**Что должно появиться:** Список твоих процессов, а не каталог чужих шаблонов.\n\n![Скриншот: n8n: раздел Personal в левом меню](https://elaz-ed.vercel.app/learning/ai-practice/ui/n8n-personal.png)\n\nn8n: раздел Personal в левом меню. Нажми на изображение, чтобы увеличить. Иллюстрация веб-интерфейса; расположение элементов в твоей версии может отличаться.\n\n#### Шаг 2\n\n**Куда нажать / что ввести:** Справа сверху нажми Create workflow.\n\n**Зачем:** Открыть пустой холст процесса.\n\n**Что должно появиться:** Редактор, в котором добавляются и соединяются узлы.\n\n![Скриншот: n8n: кнопка Create workflow справа сверху](https://elaz-ed.vercel.app/learning/ai-practice/ui/n8n-create.png)\n\nn8n: кнопка Create workflow справа сверху. Нажми на изображение, чтобы увеличить. Иллюстрация веб-интерфейса; расположение элементов в твоей версии может отличаться.\n\n#### Шаг 3\n\n**Куда нажать / что ввести:** Добавь Manual Trigger, затем через «+» найди Edit Fields (Set). В нём задай title и time из учебного брифа.\n\n**Зачем:** Начать с ручного запуска и явных данных.\n\n**Что должно появиться:** На холсте два соединённых узла. В данных второго видны тема и время.\n\n#### Шаг 4\n\n**Куда нажать / что ввести:** Через «+» добавь If и проверь, что time не пустое. Соедини true с результатом, false — с сообщением «Нужно время». Выполни ручной запуск, затем очисти time и повтори.\n\n**Зачем:** Проверить успешный путь и ошибку до подключения модели.\n\n**Что должно появиться:** С полным временем проходит true, с пустым — false. Журнал запусков показывает пройденные узлы.\n\n**Если экран отличается:** Подписи узлов могут отличаться по версии: Edit Fields также называется Set. Этот ручной пример не устраняет дубли автоматически: для повторного события нужен постоянный журнал из задания урока.\n\n## Разобранный пример\n\nСобытие A поступило дважды. Первый запуск создал draft-A.md и записал статус ready. Второй нашёл тот же ключ и вернул существующий путь. Это желательное поведение.\n\nЕсли публикация вернула таймаут, запись становится unknown. Сначала проверяешь журнал или наличие сообщения у получателя; только потом решаешь, повторять ли отправку. Ошибка 429 обычно означает ограничение частоты — учитывай указанное время повтора.\n\n## Сделай по шагам\n\n1. Нарисуй схему из 4 шагов: вход, проверка обязательных полей, генерация черновика, ручное подтверждение.\n\n2. В n8n, другом редакторе или простом скрипте собери учебный поток. Используй данные брифа; конечный шаг сохраняет файл или строку в тестовую таблицу.\n\n3. Добавь журнал: event_id, status, result_path, error. Прогони одно событие дважды и сравни число результатов.\n\n4. Смоделируй пустое время встречи и недоступный сервис. Запиши, где процесс останавливается и как возобновляется без создания второго результата.\n\n## Самостоятельная работа\n\nСохрани схему, журнал двух повторных запусков и три правила восстановления. Достаточно учебного процесса без доступа к реальным каналам и клиентской базе.\n\n## Критерии готовности\n\nПовтор события не создаёт второй результат; неполный бриф останавливается; неизвестный результат не превращается в успех; публикация требует отдельного решения.\n\n## Проверь себя\n\nПочему нельзя ставить статус published до ответа внешнего сервиса?\n\nСначала ответь своими словами, затем сравни с разбором.\n\n## Разбор ответа\n\nПотому что журнал заявит об успехе, которого могло не быть. Сохраняй подтверждённый ID результата; при неопределённости используй отдельный статус и сверку.\n\n## Ссылки для практики\n\n- [n8n: документация и учебные процессы](https://docs.n8n.io/)\n- [n8n: облачный пробный доступ и планы](https://n8n.io/pricing/)\n- [Make: кредиты и расходы ИИ](https://help.make.com/credits)\n\nСледующий шаг: сохрани результат этого урока и переходи к следующему.","cover_url":"https://elaz-ed.vercel.app/learning/ai-practice/lesson-11.png","minutes":40,"position":11,"category":"Модуль 4 · Автоматизация"},{"key":"block-7","title":"12. Вайбкодинг: создай свою первую страницу","subtitle":"Создашь локальную страницу по техническому заданию и научишься проверять результат агента.","body":"Модуль 5 · Вайбкодинг\n\nАктуальность: 26 октября 2026. Лимиты и доступность сверяй в своём аккаунте перед запуском.\n\n## Чему научишься\n\nСоздашь локальную страницу по техническому заданию и научишься проверять результат агента.\n\nОриентир: 45 минут вместе с практикой. Сохраняй файлы: они пригодятся в итоговом проекте.\n\n![Схема урока](https://elaz-ed.vercel.app/learning/ai-practice/lesson-12.png)\n\n## Как это работает\n\nВайбкодинг — работа над программой через описание желаемого поведения и проверку изменений. Тебе не обязательно писать каждую строку вручную, но нужно понимать, что должно получиться и как это проверить. Агент может ошибиться, поэтому маленькие шаги удобнее большого запроса «сделай всё».\n\nНачнём с одной локальной HTML-страницы. HTML задаёт структуру, CSS — вид, JavaScript — поведение. Браузер открывает файл index.html без сервера, если страница не обращается к внешним API. Локальное подтверждение не означает отправку заявки: для настоящей формы нужны сервер и хранение данных.\n\nТехническое задание описывает три состояния: пустая форма, ошибка и успешный локальный результат. Кнопка, которая всегда показывает «успех», не решает задачу, даже если выглядит красиво. Изменяй за один проход одну функцию и проверяй её до следующего шага.\n\n## Наглядно: разберём процесс\n\nПоследовательность: Пустая форма → Ошибка ввода → Заполненное имя → Честное подтверждение. Смотри автоматически или переключай шаги самостоятельно.\n\n```lesson-animation\nform\n```\n\n## Какие инструменты выбрать\n\nДля вайбкодинга можно начать с чата, который выдаёт HTML, или использовать Cursor — редактор с агентом для кода. Gemini CLI — вариант работы через терминал, когда уже умеешь открывать папку и запускать команды. OpenBot пригодится позже для нескольких ролей, а не обязателен для первой страницы.\n\n## Бесплатно и платно\n\nCursor Free даёт ограниченное использование ИИ. В Gemini CLI доступ зависит от способа входа и лимитов, описанных в официальном README. Сначала сделай маленький проект в доступном бесплатном варианте. Платный доступ полезен, когда упираешься в объём работы или нужную функцию. Затраты на хостинг и внешние API считаются отдельно от редактора.\n\n## Первый запуск\n\n### Открой свою первую страницу\n\nДля каждого шага смотри три вещи: что нажать, зачем и какой результат проверить. Английские названия оставлены рядом с русскими, чтобы их можно было найти в интерфейсе.\n\n#### Шаг 1\n\n**Куда нажать / что ввести:** Нажми ссылку «Начальная страница» внизу урока.\n\n**Зачем:** Посмотреть готовый учебный пример.\n\n**Что должно появиться:** Открылась форма клуба Фокус. Пока это локальная демонстрация, без настоящей регистрации.\n\n#### Шаг 2\n\n**Куда нажать / что ввести:** Нажми кнопку формы с пустым именем, затем введи пробелы и повтори.\n\n**Зачем:** Проверить два ошибочных состояния.\n\n**Что должно появиться:** Рядом с полем появляется сообщение, а не ложное подтверждение отправки.\n\n#### Шаг 3\n\n**Куда нажать / что ввести:** Введи «Алия» и нажми кнопку ещё раз.\n\n**Зачем:** Проверить успешное локальное состояние.\n\n**Что должно появиться:** Сообщение честно говорит, что данные никуда не отправлены.\n\n#### Шаг 4\n\n**Куда нажать / что ввести:** Для своей версии попроси чат выдать один index.html. Сохрани его как обычный текст с расширением .html и открой в браузере.\n\n**Зачем:** Перейти от просмотра к собственному изменению.\n\n**Что должно появиться:** Твой файл открывается; после изменения надписи и обновления браузера видна новая версия.\n\n**Если экран отличается:** На телефоне можно проверить пример, но редактировать файлы удобнее на компьютере. Не сохраняй HTML как документ Word и не называй файл index.html.txt.\n\n## Разобранный пример\n\nЗапрос: «Создай один index.html для вымышленного клуба Фокус: тема, дата из brief.md, поле имени и кнопка “Проверить заявку”. Без внешних библиотек и серверных запросов. При пустом имени покажи ошибку; при заполненном — “Учебная заявка проверена, никуда не отправлена”. Поддержи ширину 360 px. После кода перечисли три проверки».\n\nРазница между учебной и рабочей формой должна быть видна пользователю. Нельзя писать «Вы зарегистрированы», если данные нигде не сохраняются.\n\n## Сделай по шагам\n\n1. Создай отдельную папку focus-page. Скачай page-starter.html и сохрани копию как index.html. Открой её двойным щелчком в браузере.\n\n2. В доступном чате или редакторе с агентом передай задание из примера. Попроси кратко объяснить, какие части отвечают за структуру, стиль и проверку имени.\n\n3. Сохрани предложенный файл и открой в браузере. Проверь пустое имя, пробелы и обычное имя. Уменьши окно до мобильной ширины.\n\n4. Попроси исправить один найденный дефект. Сравни версии и повтори все три проверки. Сохрани README с инструкцией открытия и ограничением «данные никуда не отправляются».\n\n## Самостоятельная работа\n\nСобери index.html и checks.md с результатами трёх проверок. Затем переходи к отдельному уроку OpenCode, чтобы повторить изменение в рабочем пространстве агента.\n\n## Критерии готовности\n\nФайл открывается локально; тема и дата совпадают с брифом; ошибка видна рядом с полем; пробелы не считаются именем; успешный ответ честно описывает учебную проверку; на 360 px нет горизонтальной прокрутки.\n\n## Проверь себя\n\nКнопка пишет «Заявка отправлена», но в коде нет сетевого запроса. Это готовая форма регистрации?\n\nСначала ответь своими словами, затем сравни с разбором.\n\n## Разбор ответа\n\nНет. Это только локальный интерфейс. Исправь сообщение и отдельно спроектируй серверный этап, если нужна настоящая регистрация.\n\n## Ссылки для практики\n\n- [Начальная страница](https://elaz-ed.vercel.app/learning/ai-practice/page-starter.html)\n- [Тестовые заявки](https://elaz-ed.vercel.app/learning/ai-practice/registrations.json)\n- [Node.js: установка](https://nodejs.org/en/download)\n- [Cursor: доступ и ограничения тарифов](https://cursor.com/pricing)\n- [Gemini CLI: официальный старт](https://github.com/google-gemini/gemini-cli)\n\nСледующий шаг: сохрани результат этого урока и переходи к следующему.","cover_url":"https://elaz-ed.vercel.app/learning/ai-practice/lesson-12.png","minutes":45,"position":12,"category":"Модуль 5 · Вайбкодинг"},{"key":"block-opencode","title":"13. OpenCode: план, первая правка и проверка проекта","subtitle":"Откроешь небольшой проект в OpenCode Desktop, выберешь провайдера и выполнишь одну проверяемую правку.","body":"Модуль 5 · Вайбкодинг\n\nАктуальность: 26 октября 2026. Лимиты и доступность сверяй в своём аккаунте перед запуском.\n\n## Чему научишься\n\nОткроешь небольшой проект в OpenCode Desktop, выберешь провайдера и выполнишь одну проверяемую правку.\n\nОриентир: 45 минут вместе с практикой. Сохраняй файлы: они пригодятся в итоговом проекте.\n\n![Схема урока](https://elaz-ed.vercel.app/learning/ai-practice/lesson-13.png)\n\n## Как это работает\n\nOpenCode — отдельное приложение для работы с кодом, не приложение Claude. Для этой практики выбираем актуальный OpenCode Desktop из руководства V2: терминал не нужен для основного пути. Бесплатная доступность приложения не означает бесплатную работу любой подключённой модели. Проверь провайдера, доступный способ входа и лимиты.\n\nДля новичка важнее цикл «описать → спланировать → изменить → проверить», чем длинная автономная сессия. Plan предназначен для планирования, Build — для работы над кодом. Выбирай нужного агента в доступном интерфейсе или явно проси сначала только предложить план. Не переноси горячие клавиши из старого терминального руководства в приложение.\n\nФайл AGENTS.md сохраняет инструкции проекта. Укажи в нём простые правила: один локальный HTML, без внешних ключей и библиотек, проверять мобильную ширину и пустой ввод. Перед началом сохрани исходный файл отдельно или сделай коммит, чтобы сравнить изменения и восстановить рабочую версию.\n\n## Наглядно: разберём процесс\n\nПоследовательность: Сначала план → Посмотри изменение → Прогони три случая → Сохрани рабочую версию. Смотри автоматически или переключай шаги самостоятельно.\n\n```lesson-animation\nreview\n```\n\n## Какие инструменты выбрать\n\nOpenCode — основной инструмент практики этого урока. Cursor и Gemini CLI — альтернативы для сравнения рабочего процесса. Выбирай по удобству, доступному провайдеру, управлению файлами и понятности проверки.\n\n## Бесплатно и платно\n\nНе обещаем бесплатную работу любой модели: проверь условия выбранного провайдера до подключения. Публичный код редактора и бесплатная квота модели — разные вещи. Платный доступ нужен при подтверждённой потребности в конкретном объёме или модели.\n\n## Первый запуск\n\n### OpenCode Desktop: проект, модель и первая правка\n\nДля каждого шага смотри три вещи: что нажать, зачем и какой результат проверить. Английские названия оставлены рядом с русскими, чтобы их можно было найти в интерфейсе.\n\n#### Шаг 1\n\n**Куда нажать / что ввести:** Открой opencode.ai/v2/docs и найди раздел Desktop. Скачай приложение для своей ОС.\n\n**Зачем:** Начать с актуального приложения, а не старого терминального руководства.\n\n**Что должно появиться:** Установлено приложение OpenCode Desktop; это отдельный инструмент, не Claude Desktop.\n\n#### Шаг 2\n\n**Куда нажать / что ввести:** Нажми Open project и выбери папку с index.html.\n\n**Зачем:** Дать агенту нужный проект.\n\n**Что должно появиться:** Открыта именно учебная папка, а не весь диск.\n\n#### Шаг 3\n\n**Куда нажать / что ввести:** В Providers настрой доступного провайдера, затем открой Select model. Создай New session.\n\n**Зачем:** Выбрать модель и начать отдельную задачу.\n\n**Что должно появиться:** Виден выбранный провайдер и доступная модель; условия оплаты проверены до работы.\n\n#### Шаг 4\n\n**Куда нажать / что ввести:** В поле сообщения вставь задание урока и попроси сначала план без правок. После проверки разреши одно изменение; открой index.html в браузере.\n\n**Зачем:** Проверить реальную работу приложения.\n\n**Что должно появиться:** Изменён нужный файл, три проверки пройдены, исходная копия сохранена.\n\n**Если экран отличается:** Для приложения используй руководство V2 → Desktop. Open project открывает папку; Providers управляет подключениями, Select model — моделью, New session — новым разговором о коде. Не путай OpenCode Desktop с Claude Desktop.\n\n## Разобранный пример\n\nЗадание: «В @index.html добавь поле имени и кнопку “Проверить заявку”. Пустое имя показывает ошибку рядом с полем. Непустое имя показывает локальное подтверждение, без отправки на сервер. Сначала предложи план и три проверки. Меняй только index.html».\n\nОжидаемые проверки: пустая строка → ошибка; пробелы → ошибка; “Алия” → локальное подтверждение. Отдельно проверь, что интерфейс не заявляет об отправке реальной регистрации.\n\n## Сделай по шагам\n\n1. Открой актуальное руководство OpenCode V2 → Desktop и скачай приложение для своей ОС. Установи его по подсказкам и запусти. Основной путь урока не требует установки CLI.\n\n2. В приложении выбери Open project и папку со страницей предыдущего урока. В Providers проверь способ подключения, затем в Select model выбери доступную модель. Если нужен платный доступ, сначала оцени условия; покупка для прохождения не обязательна.\n\n3. Создай New session и попроси сначала описать план без изменения файлов. В AGENTS.md запиши: один index.html, без внешних ключей и библиотек, проверить пустое имя и пробелы. Проверь, что план не добавляет сервер и ненужные файлы.\n\n4. После просмотра плана разреши одну правку. Открой index.html в браузере, прогони три проверки и ширину 360 px. Посмотри изменённые файлы, сохрани удачную версию или восстанови исходную копию.\n\n## Самостоятельная работа\n\nСохрани AGENTS.md, index.html и checks.md с тремя входами и фактическими результатами. Напиши, какой провайдер выбран и какие ограничения доступа действуют, не записывая ключи.\n\n## Критерии готовности\n\nПустое имя и пробелы не проходят; корректное имя даёт локальный результат; внешняя регистрация не имитируется; изменён только нужный файл; способ возврата к прежней версии проверен.\n\n## Проверь себя\n\nOpenCode предлагает подключить несколько MCP-серверов для простой кнопки. Это необходимо?\n\nСначала ответь своими словами, затем сравни с разбором.\n\n## Разбор ответа\n\nОбычно нет: для локального HTML достаточно файлов и проверки в браузере. Дополнительные серверы добавляют возможности и контекст, поэтому подключай только те, без которых конкретная задача не решается.\n\n## Ссылки для практики\n\n- [OpenCode V2: Desktop для своей ОС](https://opencode.ai/v2/docs/#desktop)\n- [Провайдеры V2](https://opencode.ai/v2/docs/providers/)\n- [Инструкции AGENTS.md в V2](https://opencode.ai/v2/docs/instructions/)\n\nСледующий шаг: сохрани результат этого урока и переходи к следующему.","cover_url":"https://elaz-ed.vercel.app/learning/ai-practice/lesson-13.png","minutes":45,"position":13,"category":"Модуль 5 · Вайбкодинг"},{"key":"block-agent-reach","title":"14. Итоговый проект: выпусти и проверь весь комплект","subtitle":"Соединишь навыки в один проект и оценишь результат по понятной шкале.","body":"Модуль 5 · Вайбкодинг\n\nАктуальность: 26 октября 2026. Лимиты и доступность сверяй в своём аккаунте перед запуском.\n\n## Чему научишься\n\nСоединишь навыки в один проект и оценишь результат по понятной шкале.\n\nОриентир: 60 минут вместе с практикой. Сохраняй файлы: они пригодятся в итоговом проекте.\n\n![Схема урока](https://elaz-ed.vercel.app/learning/ai-practice/lesson-14.png)\n\n## Как это работает\n\nИтог курса — не список опробованных сервисов, а воспроизводимый комплект материалов. Инструменты можно заменить; важнее сохранить входные данные, последовательность действий и проверку результата.\n\nСобери запуск клуба «Фокус» или своего проекта: проверенный бриф, исследование, текст, два визуальных формата, ролик с озвучкой и схему повторного выпуска. Если какой-то этап не нужен твоему проекту, сделай учебный образец и объясни решение. Не публикуй вымышленные учебные данные как настоящее мероприятие.\n\nОценивай качество отдельно от скорости. Быстрый материал с неверной датой не проходит работу. Запиши время и затраты, но сначала проверь факты, читаемость и повторяемость.\n\n## Какие инструменты выбрать\n\nВыбери по одному решению для текста, изображения, видео, голоса, музыки, кода и автоматизации. Критерий выбора — конкретный результат проекта, доступность и возможность проверить вывод.\n\n## Бесплатно и платно\n\nСоставь budget.csv: сервис, бесплатный лимит, фактический расход, нужная платная функция, стоимость на официальной странице, решение «нужно / пока не нужно». Учитывай повторные генерации, права на использование, экспорт и отдельный API. Покупка подписок не является условием завершения курса.\n\n## Первый запуск\n\n### Собери и проверь итоговую папку\n\nДля каждого шага смотри три вещи: что нажать, зачем и какой результат проверить. Английские названия оставлены рядом с русскими, чтобы их можно было найти в интерфейсе.\n\n#### Шаг 1\n\n**Куда нажать / что ввести:** Открой папку проекта в проводнике и создай README.md со списком финальных файлов.\n\n**Зачем:** Показать, какие версии использовать.\n\n**Что должно появиться:** Для каждого результата есть понятное имя и назначение.\n\n#### Шаг 2\n\n**Куда нажать / что ввести:** Открой brief.md рядом с post.md, изображениями и роликом. По очереди сверь тему, дату и время.\n\n**Зачем:** Найти противоречия между форматами.\n\n**Что должно появиться:** Одни и те же данные во всех материалах.\n\n#### Шаг 3\n\n**Куда нажать / что ввести:** Открой review.md и оцени пять критериев из задания. Укажи файл или проверку для каждого балла.\n\n**Зачем:** Обосновать оценку результата.\n\n**Что должно появиться:** Понятно, откуда взялась итоговая сумма, а не просто «мне нравится».\n\n#### Шаг 4\n\n**Куда нажать / что ввести:** Измени учебную дату в брифе и повтори выпуск. Затем открой каждый новый файл.\n\n**Зачем:** Проверить воспроизводимость процесса.\n\n**Что должно появиться:** Старая дата не осталась на обложке, в голосе или видео; повторы не создали лишних публикаций.\n\n**Если экран отличается:** Папка может находиться в проводнике или выбранном облачном хранилище. Проверяй содержимое файлов, а не только имена и отметки «готово».\n\n## Разобранный пример\n\nСтруктура сдачи: brief.md; evidence.csv; post.md; cover.png; story.png; video.mp4; transcript-checked.md; workflow.md; review.md.\n\nВ review.md напиши: что проверено вручную, какие файлы финальные, где ограничения и сколько времени заняли исправления. Папка с десятью файлами final-final2 не объясняет, какую версию использовать.\n\n## Сделай по шагам\n\n1. Сверь все материалы с одним актуальным brief.md. Дата, время, тема и следующий шаг должны совпадать во всех форматах.\n\n2. Проведи тест телефона: текст читается без увеличения, ролик понятен без звука, голос различим без картинки.\n\n3. Запусти процесс повторно с новой учебной датой. Проверь, какие файлы обновились, и найди места, где старое значение осталось вручную.\n\n4. Заполни рубрику: факты 0–2, ясность 0–2, визуал и звук 0–2, обработка ошибок 0–2, воспроизводимость 0–2. На каждый балл приложи конкретный файл или результат проверки.\n\n## Самостоятельная работа\n\nСдать папку проекта и review.md. Цель — минимум 8/10, при этом факты должны получить 2/2: неверная дата или выдуманный факт требуют исправления независимо от общей суммы.\n\n## Критерии готовности\n\nКомплект открывается; все версии согласованы; источники проверяемы; повторный запуск не создаёт дубли; другой человек понимает по README, как повторить процесс.\n\n## Проверь себя\n\nВсё красиво, но повторный запуск оставил старую дату в ролике. Проект готов?\n\nСначала ответь своими словами, затем сравни с разбором.\n\n## Разбор ответа\n\nНет. Исправь связь данных и шаблона, добавь проверку даты в ролике и повтори смену даты. Воспроизводимость проверяется действием, а не обещанием.\n\n## Ссылки для практики\n\n- [Бриф для нового запуска](https://elaz-ed.vercel.app/learning/ai-practice/brief.md)\n- [Схема и инструкция OpenBot](https://openbot.run/)\n- [Исследование через Agent Reach](https://github.com/Panniantong/Agent-Reach)\n\nКурс завершён, когда комплект прошёл проверку и повторный запуск. Сохрани свою оценку и список следующих улучшений.","cover_url":"https://elaz-ed.vercel.app/learning/ai-practice/lesson-14.png","minutes":60,"position":14,"category":"Модуль 5 · Вайбкодинг"}]}$payload$::jsonb; mapping jsonb; newer jsonb; extra jsonb; added jsonb := '{}'::jsonb; cid bigint; revision_cid bigint; l jsonb; lid bigint;
begin
select value->'lessons',(value->>'course_id')::bigint into mapping,cid from public.settings where key='content_import:ai-practice-2026-10-25-v1';
select value->'lessons',(value->>'course_id')::bigint into newer,revision_cid from public.settings where key='content_revision:ai-practice-2026-10-26-v2';
if cid is null or revision_cid is distinct from cid then raise exception 'Course mappings missing or inconsistent'; end if;
select value->'lessons' into extra from public.settings where key='content_revision:ai-practice-training-2026-10-26-v3';
mapping := mapping || newer || coalesce(extra,'{}'::jsonb);
if (select count(*) from public.lessons where course_id=cid) not in (10,13,14) then raise exception 'Unexpected course lesson count'; end if;
for l in select value from jsonb_array_elements(p->'lessons') loop
 lid := (mapping->>(l->>'key'))::bigint;
 if lid is null then
  if l->>'key' not in('block-connections','block-music','block-opencode','block-native-automation') then raise exception 'Missing lesson mapping %',l->>'key'; end if;
  insert into public.lessons(kind,title,body,course_id,position,published,published_at,free_preview,xp,quiz) values('lesson',l->>'title',l->>'body',cid,(l->>'position')::int,true,now(),true,100,'[]'::jsonb) returning id into lid;
 end if;
 added := added || jsonb_build_object(l->>'key',lid);
 update public.lessons set title=l->>'title',subtitle=l->>'subtitle',body=l->>'body',cover_url=l->>'cover_url',minutes=(l->>'minutes')::int,position=(l->>'position')::int,category=l->>'category' where id=lid and course_id=cid;
 if not found then raise exception 'Wrong course lesson %',lid; end if;
end loop;
update public.courses set title=p->'course'->>'title',subtitle=p->'course'->>'subtitle',description=p->'course'->>'description' where id=cid;
insert into public.settings(key,value) values('content_revision:ai-practice-training-2026-10-26-v3',jsonb_build_object('course_id',cid,'lessons',added,'lesson_count',14,'version',p->>'revision')) on conflict(key) do update set value=excluded.value;
end; $training$;
commit;
select id,title,subtitle from public.courses where id=(select (value->>'course_id')::bigint from public.settings where key='content_revision:ai-practice-training-2026-10-26-v3');
